  webServer: [
    {
      command: 'npm run dev',
      url: 'http://localhost:5173',
      reuseExistingServer: !process.env.CI,
      cwd: './',
    },
    {
      command: 'npm run server',
      url: 'http://localhost:5005',
      reuseExistingServer: !process.env.CI,
      cwd: '../server',
    }
  ],
});

