import React, { useState, useEffect } from "react";
import { Box, Typography, Button, TextField } from "@mui/material";

// Sub-components
import CommentBubble from "./comments/CommentBubble";
import ReplyBubble from "./comments/ReplyBubble";
import ConfirmDeleteDialog from "./ConfirmDeleteDialog";

export default function CommentThread({
	comment,
	localPost,
	currentUser,
	highlightId,
	openLikes,
	handleToggleLike,
	apiCall,
	formatTime,
	renderContentWithTags,
	clickableStyle,
}) {
	const [isReplying, setIsReplying] = useState(false);
	const [nestedReplyText, setNestedReplyText] = useState("");
	const [isExpanded, setIsExpanded] = useState(false);

	// Single dialog state handles both comments and replies
	const [deleteTarget, setDeleteTarget] = useState(null); // { isReply: boolean, replyId: string|null }

	useEffect(() => {
		if (highlightId && comment.replies?.some((r) => r._id === highlightId))
			setIsExpanded(true);
	}, [highlightId, comment.replies]);

	const handleSubmitNestedReply = () => {
		if (!nestedReplyText.trim() || !currentUser) return;
		apiCall(
			`/api/forum/${localPost._id}/comments/${comment._id}/replies`,
			"POST",
			{
				authorId: currentUser.id,
				authorName: currentUser.name,
				content: nestedReplyText.trim(),
			},
		);
		setNestedReplyText("");
		setIsReplying(false);
		setIsExpanded(true);
	};

	const confirmDelete = async () => {
		if (!deleteTarget) return;
		let endpoint = `/api/forum/${localPost._id}/comments/${comment._id}`;
		if (deleteTarget.isReply)
			endpoint += `/replies/${deleteTarget.replyId}`;
		await apiCall(endpoint, "DELETE", { userId: currentUser.id });
		setDeleteTarget(null);
	};

	return (
		<Box
			id={`comment-${comment._id}`}
			className={highlightId === comment._id ? "highlight-active" : ""}
			sx={{ display: "flex", flexDirection: "column", p: 0.5 }}
		>
			{/* MAIN COMMENT */}
			<CommentBubble
				comment={comment}
				localPostId={localPost._id}
				currentUser={currentUser}
				highlightId={highlightId}
				openLikes={openLikes}
				handleToggleLike={handleToggleLike}
				formatTime={formatTime}
				renderContentWithTags={renderContentWithTags}
				clickableStyle={clickableStyle}
				promptDelete={() =>
					setDeleteTarget({ isReply: false, replyId: null })
				}
				onReply={() => {
					setIsReplying(true);
					setNestedReplyText(`@${comment.authorName} `);
				}}
			/>

			{/* REPLIES TOGGLE */}
			{comment.replies?.length > 0 && (
				<Typography
					variant="caption"
					onClick={() => setIsExpanded(!isExpanded)}
					sx={{
						ml: 5,
						mt: 0.5,
						cursor: "pointer",
						fontWeight: "bold",
						color: "text.secondary",
					}}
				>
					{isExpanded
						? "Hide replies"
						: `↪ View ${comment.replies.length} replies`}
				</Typography>
			)}

			{/* NESTED REPLIES LOOP */}
			{isExpanded &&
				comment.replies?.map((reply) => (
					<ReplyBubble
						key={reply._id}
						reply={reply}
						commentId={comment._id}
						localPostId={localPost._id}
						currentUser={currentUser}
						highlightId={highlightId}
						openLikes={openLikes}
						handleToggleLike={handleToggleLike}
						formatTime={formatTime}
						renderContentWithTags={renderContentWithTags}
						clickableStyle={clickableStyle}
						promptDelete={() =>
							setDeleteTarget({
								isReply: true,
								replyId: reply._id,
							})
						}
						onReply={() => {
							setIsReplying(true);
							setNestedReplyText(`@${reply.authorName} `);
						}}
					/>
				))}

			{/* NESTED REPLY INPUT */}
			{isReplying && (
				<Box
					sx={{
						display: "flex",
						gap: 1,
						mt: 1,
						alignItems: "flex-end",
						ml: { xs: 4, sm: 6 },
					}}
				>
					<TextField
						fullWidth
						size="small"
						multiline
						maxRows={4}
						placeholder={`Reply to ${comment.authorName}...`}
						value={nestedReplyText}
						onChange={(e) => setNestedReplyText(e.target.value)}
						onKeyDown={(e) => {
							if (e.key === "Enter" && !e.shiftKey) {
								e.preventDefault();
								handleSubmitNestedReply();
							}
						}}
						sx={{
							"& .MuiOutlinedInput-root": {
								borderRadius: "20px",
								bgcolor: "background.paper",
								py: 1,
								px: 2,
							},
						}}
					/>
					<Button
						size="small"
						variant="contained"
						onClick={handleSubmitNestedReply}
						disabled={!nestedReplyText.trim()}
						sx={{
							borderRadius: 5,
							minWidth: "50px",
							mb: 0.5,
							"&:active": { transform: "scale(0.95)" },
						}}
					>
						Post
					</Button>
				</Box>
			)}

			{/* SHARED DELETE DIALOG */}
			<ConfirmDeleteDialog
				open={!!deleteTarget}
				onClose={() => setDeleteTarget(null)}
				onConfirm={confirmDelete}
				itemName={deleteTarget?.isReply ? "reply" : "comment"}
			/>
		</Box>
	);
}

import React from 'react';
import {
	Dialog,
	DialogTitle,
	DialogContent,
	DialogActions,
	Button,
	Typography,
} from "@mui/material";
import { TrashIcon } from "./Icons";

export default function ConfirmDeleteDialog({
	open,
	onClose,
	onConfirm,
	itemName = "item",
}) {
	return (
		<Dialog
			open={open}
			onClose={onClose}
			PaperProps={{ sx: { borderRadius: 3, p: 1 } }}
		>
			<DialogTitle
				sx={{
					fontWeight: "bold",
					display: "flex",
					alignItems: "center",
					gap: 1,
					color: "error.main",
				}}
			>
				<TrashIcon /> Confirm Deletion
			</DialogTitle>
			<DialogContent>
				<Typography>
					Are you sure you want to permanently delete this {itemName}?
					This action cannot be undone.
				</Typography>
			</DialogContent>
			<DialogActions sx={{ px: 3, pb: 2 }}>
				<Button
					onClick={onClose}
					color="inherit"
					sx={{ fontWeight: "bold", textTransform: "none" }}
				>
					Cancel
				</Button>
				<Button
					onClick={onConfirm}
					variant="contained"
					color="error"
					sx={{
						fontWeight: "bold",
						textTransform: "none",
						borderRadius: 2,
					}}
				>
					Delete
				</Button>
			</DialogActions>
		</Dialog>
	);
}

import React from 'react';
import {
	Dialog,
	DialogTitle,
	DialogContent,
	List,
	ListItemButton,
	Avatar,
	Typography,
	IconButton,
} from "@mui/material";
import { useNavigate } from "react-router-dom";

export default function LikesModal({ open, title, list, onClose }) {
	const navigate = useNavigate();

	return (
		<Dialog open={open} onClose={onClose} maxWidth="xs" fullWidth>
			<DialogTitle
				sx={{
					fontWeight: "bold",
					borderBottom: "1px solid #eee",
					textAlign: "center",
					py: 2,
					position: "relative",
				}}
			>
				{title}
				<IconButton
					onClick={onClose}
					sx={{
						position: "absolute",
						right: 8,
						top: 8,
						transition: "all 0.2s",
						"&:active": { transform: "scale(0.9)" },
					}}
				>
					✕
				</IconButton>
			</DialogTitle>
			<DialogContent sx={{ p: 0, maxHeight: 400 }}>
				<List disablePadding>
					{list.map((u) => (
						<ListItemButton
							key={u.id}
							onClick={() => {
								onClose();
								navigate(`/profile/${u.id}`);
							}}
							sx={{ py: 1.5, borderBottom: "1px solid #f5f5f5" }}
						>
							<Avatar
								src={u.profilePic}
								sx={{
									width: 40,
									height: 40,
									mr: 2,
									bgcolor: "secondary.main",
									color: "primary.main",
								}}
							>
								{!u.profilePic &&
									u.name?.charAt(0).toUpperCase()}
							</Avatar>
							<Typography fontWeight="bold">{u.name}</Typography>
						</ListItemButton>
					))}
					{list.length === 0 && (
						<Typography
							sx={{
								p: 4,
								textAlign: "center",
								color: "text.secondary",
							}}
						>
							No likes yet.
						</Typography>
					)}
				</List>
			</DialogContent>
		</Dialog>
	);
}

