// client/src/components/PostCard.jsx
import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import {
	Typography,
	Button,
	Box,
	Paper,
	Divider,
	CardActions,
	Avatar,
	AvatarGroup,
	IconButton,
	Menu,
	MenuItem,
	TextField,
	Dialog,
	Collapse,
	Chip,
} from "@mui/material";

// Separated Sub-Components
import LikesModal from "./LikesModal";
import PostCommentsInline from "./PostCommentsInline";
import ConfirmDeleteDialog from "./ConfirmDeleteDialog";
import {
	ThumbUpOutline,
	ThumbUpFilled,
	MessageCircleIcon,
	ShareIcon,
	MoreVertIcon,
	CloseIcon,
} from "./Icons";

export default function PostCard({ post, isBookmarked, onBookmarkToggle }) {
	const navigate = useNavigate();
	const currentUser = JSON.parse(localStorage.getItem("user"));

	const [isCommentModalOpen, setIsCommentModalOpen] = useState(false);
	const [isLightboxOpen, setIsLightboxOpen] = useState(false);
	const [localPost, setLocalPost] = useState(post);

	const [likesModal, setLikesModal] = useState({
		open: false,
		title: "",
		list: [],
	});
	const [isLiking, setIsLiking] = useState(false);

	const [anchorEl, setAnchorEl] = useState(null);
	const [isEditing, setIsEditing] = useState(false);
	const [editTitle, setEditTitle] = useState(post.title);
	const [editContent, setEditContent] = useState(post.content);

	// Toggles the imported dialog component
	const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);

	const urlParams = new URLSearchParams(window.location.search);
	const highlightId = urlParams.get("highlight");
	const { postId: routePostId } = useParams();
	const urlPostId = urlParams.get("postId") || routePostId;

	useEffect(() => {
		setLocalPost(post);
		setEditTitle(post.title);
		setEditContent(post.content);
	}, [post]);

	useEffect(() => {
		if (urlPostId === localPost._id) {
			if (highlightId) setIsCommentModalOpen(true);
			setTimeout(() => {
				document
					.getElementById(`post-${localPost._id}`)
					?.scrollIntoView({ behavior: "smooth", block: "center" });
			}, 300);
		}
	}, [urlPostId, highlightId, localPost._id]);

	useEffect(() => {
		if (isCommentModalOpen) {
			fetch("/api/forum/" + localPost._id + "/comments", {
				headers: { Authorization: "Bearer " + localStorage.getItem("token") }
			})
			.then(res => res.json())
			.then(data => {
				if (data.comments) {
					setLocalPost(prev => ({ ...prev, comments: data.comments }));
				}
			})
			.catch(err => console.error("Error fetching comments:", err));
		}
	}, [isCommentModalOpen, localPost._id]);
	const totalCommentsCount =
		localPost.comments?.reduce(
			(acc, c) => acc + 1 + (c.replies?.length || 0),
			0,
		) || 0;
	const hasLiked = localPost.likedBy?.includes(currentUser?.id);

	const [showHeart, setShowHeart] = useState(false);
	const [showReactions, setShowReactions] = useState(false);


	const handleDoubleTap = (e) => {
		e.preventDefault();
		// Avoid liking twice rapidly
		if (!hasLiked && !isLiking) {
			handleLike();
		}
		setShowHeart(true);
		setTimeout(() => setShowHeart(false), 1000);
	};

	const openLikes = (e, title, list) => {
		e.stopPropagation();
		if (list?.length > 0) setLikesModal({ open: true, title, list });
	};

	const handleLike = async () => {
		if (!currentUser) return alert("You must be logged in to like posts!");
		if (isLiking) return;

		setIsLiking(true);
		try {
			const res = await fetch(
				`${import.meta.env.VITE_API_URL}/api/forum/${localPost._id}/like`,
				{
					method: "PUT",
					headers: { "Content-Type": "application/json" },
					body: JSON.stringify({
						userId: currentUser.id,
						userName: currentUser.name,
					}),
				},
			);
			if (res.ok) setLocalPost(await res.json());
		} catch (err) {
			console.error(err);
		} finally {
			setIsLiking(false);
		}
	};

	const handleSaveEdit = async () => {
		if (!editTitle.trim() || !editContent.trim()) return;
		try {
			const res = await fetch(
				`${import.meta.env.VITE_API_URL}/api/forum/${localPost._id}`,
				{
					method: "PUT",
					headers: {
						"Content-Type": "application/json",
						Authorization: `Bearer ${localStorage.getItem("token")}`,
					},
					body: JSON.stringify({
						userId: currentUser.id,
						title: editTitle,
						content: editContent,
					}),
				},
			);
			const data = await res.json();

			if (!res.ok) return alert(data.message || "Failed to update.");
			if (data.message === "Post submitted for review.")
				alert(
					"Your edit has been sent for admin review due to our spam filters.",
				);
			else setLocalPost(data);

			setIsEditing(false);
		} catch (err) {
			console.error(err);
		}
	};

	const confirmDeletePost = async () => {
		try {
			await fetch(
				`${import.meta.env.VITE_API_URL}/api/forum/${localPost._id}`,
				{
					method: "DELETE",
					headers: {
						"Content-Type": "application/json",
						Authorization: `Bearer ${localStorage.getItem("token")}`,
					},
					body: JSON.stringify({ userId: currentUser.id }),
				},
			);
			setIsCommentModalOpen(false);
		} catch (err) {
			console.error(err);
		}
	};

	const toggleBookmark = async () => {
		try {
			const res = await fetch("/api/forum/" + localPost._id + "/bookmark", {
				method: "PUT",
				headers: {
					"Content-Type": "application/json",
					Authorization: "Bearer " + localStorage.getItem("token")
				},
				body: JSON.stringify({ userId: currentUser.id }),
			});
			if (res.ok) {
				const data = await res.json();
				if (onBookmarkToggle) onBookmarkToggle(data.isBookmarked);
			}
		} catch (err) {
			console.error(err);
		}
	};

	const formatTime = (dateString) => {
		if (!dateString) return "Just now";
		const diff = Date.now() - new Date(dateString).getTime();
		const mins = Math.floor(diff / 60000);
		if (mins < 1) return "Just now";
		if (mins < 60) return `${mins}m ago`;
		const hrs = Math.floor(mins / 60);
		if (hrs < 24) return `${hrs}h ago`;
		const days = Math.floor(hrs / 24);
		if (days < 7) return `${days}d ago`;
		return new Date(dateString).toLocaleDateString("en-US", { month: "short", day: "numeric" });
	};

	const actionBtnStyle = {
		textTransform: "none",
		fontWeight: 600,
		flex: 1,
		minWidth: 0,
		borderRadius: 2,
		transition: "all 0.1s ease",
		"&:hover": { backgroundColor: "rgba(0,0,0,0.04)" },
		"&:active": { transform: "scale(0.95)" },
	};
	const images = localPost.imageUrls?.length > 0 ? localPost.imageUrls : (localPost.imageUrl ? [localPost.imageUrl] : []);
	const [activeLightboxIndex, setActiveLightboxIndex] = useState(0);

	return (
		<>
			<style>
				{`
					@keyframes highlightFlash { 0% { background-color: rgba(0, 204, 102, 0.4); transform: scale(1.02); } 100% { background-color: transparent; transform: scale(1); } }
					.highlight-active { animation: highlightFlash 3s ease-out; border-radius: 8px; }
					@keyframes highlightPostFlash { 0% { border-color: #006633; box-shadow: 0 0 20px rgba(0, 102, 51, 0.4); transform: scale(1.02); } 100% { border-color: #e0e0e0; box-shadow: 0 4px 15px rgba(0,0,0,0.05); transform: scale(1); } }
					.highlight-post-active { animation: highlightPostFlash 3s ease-out; }
					@keyframes popAndFade { 
						0% { transform: translate(-50%, -50%) scale(0.5); opacity: 0; } 
						30% { transform: translate(-50%, -50%) scale(1.2); opacity: 1; } 
						50% { transform: translate(-50%, -50%) scale(1); opacity: 1; } 
						100% { transform: translate(-50%, -50%) scale(1.5); opacity: 0; } 
					}
				`}
			</style>

			<Paper
				id={`post-${localPost._id}`}
				elevation={0}
				className={
					urlPostId === localPost._id && !highlightId
						? "highlight-post-active"
						: ""
				}
				sx={{
					width: "100%",
					display: "block",
					boxSizing: "border-box",
					p: { xs: 2, sm: 3 },
					border: "1px solid",
					borderColor: "divider",
					borderRadius: 4,
					userSelect: "none",
					bgcolor: 'background.paper',
					backgroundImage: 'linear-gradient(to bottom right, rgba(255,255,255,0.05), rgba(0,0,0,0.01))',
					backdropFilter: 'blur(10px)',
					transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
					"&:hover": {
						borderColor: "primary.light",
						boxShadow: "0 12px 30px rgba(0, 102, 51, 0.12)",
						transform: "translateY(-4px)",
					},
				}}
			>
				{/* POST HEADER */}
				<Box
					sx={{
						display: "flex",
						alignItems: "flex-start",
						gap: 1.5,
						mb: 2,
					}}
				>
					<Avatar
						src={localPost.authorPic}
						onClick={() =>
							localPost.authorId && navigate(`/profile/${localPost.authorId}`)
						}
						sx={{
							bgcolor: "secondary.main",
							color: "primary.main",
							fontWeight: "bold",
							cursor: "pointer",
							"&:active": { transform: "scale(0.95)" },
						}}
					>
						{!localPost.authorPic &&
							(localPost.authorName
								? localPost.authorName?.charAt(0).toUpperCase()
								: "?")}
					</Avatar>
					<Box sx={{ flexGrow: 1 }}>
						<Typography
							variant="h6"
							fontWeight="bold"
							color="text.primary"
							sx={{ lineHeight: 1.2 }}
						>
							{localPost.title}
						</Typography>
						<Typography variant="caption" color="text.secondary">
							<strong
								onClick={() =>
									localPost.authorId && navigate(`/profile/${localPost.authorId}`)
								}
								style={{ cursor: "pointer", display: 'inline-flex', alignItems: 'center', gap: '4px' }}
							>
								{localPost.authorName || "Unknown"}
								{localPost.authorBadges?.includes("top_contributor") && (
									<Chip 
										label="Top Contributor" 
										size="small" 
										icon={<span style={{ marginLeft: 4 }}>🏅</span>}
										sx={{ 
											height: 20, fontSize: '0.65rem', fontWeight: 'bold', 
											background: 'linear-gradient(45deg, #FFD700 0%, #FFA500 100%)', 
											color: '#000', ml: 0.5 
										}} 
									/>
								)}
							</strong>{" "}
							• {formatTime(localPost.timestamp)}
							{localPost.isEdited && (
								<span
									style={{
										fontStyle: "italic",
										marginLeft: "6px",
										opacity: 0.7,
									}}
								>
									(edited)
								</span>
							)}
						</Typography>
					</Box>

					{/* 3 DOTS MENU */}
					{(currentUser?.id === localPost.authorId ||
						currentUser?.role === "admin") && (
						<Box>
							<IconButton
								onClick={(e) => setAnchorEl(e.currentTarget)}
								size="small"
								sx={{ color: "text.secondary" }}
							>
								<MoreVertIcon />
							</IconButton>
							<Menu
								anchorEl={anchorEl}
								open={Boolean(anchorEl)}
								onClose={() => setAnchorEl(null)}
								slotProps={{
									paper: {
										elevation: 2,
										sx: { borderRadius: 2 },
									},
								}}
							>
								{currentUser?.id === localPost.authorId && (
									<MenuItem
										onClick={() => {
											setIsEditing(true);
											setAnchorEl(null);
										}}
										sx={{
											fontWeight: "bold",
											fontSize: "0.9rem",
										}}
									>
										✎ Edit Post
									</MenuItem>
								)}
								<MenuItem
									onClick={() => {
										setDeleteConfirmOpen(true);
										setAnchorEl(null);
									}}
									sx={{
										color: "error.main",
										fontWeight: "bold",
										fontSize: "0.9rem",
									}}
								>
									🗑 Delete Post
								</MenuItem>
							</Menu>
						</Box>
					)}
				</Box>

				{/* POST CONTENT / EDIT MODE */}
				{isEditing ? (
					<Box
						sx={{
							mb: 3,
							p: 2,
							bgcolor: "#f9fafb",
							borderRadius: 3,
							border: "1px dashed #ccc",
						}}
					>
						<TextField
							fullWidth
							size="small"
							label="Edit Title"
							value={editTitle}
							onChange={(e) => setEditTitle(e.target.value)}
							sx={{ mb: 2, bgcolor: "background.paper" }}
						/>
						<TextField
							fullWidth
							multiline
							minRows={3}
							label="Edit Details"
							value={editContent}
							onChange={(e) => setEditContent(e.target.value)}
							sx={{ mb: 2, bgcolor: "background.paper" }}
						/>
						<Box sx={{ display: "flex", gap: 1 }}>
							<Button
								variant="contained"
								color="primary"
								onClick={handleSaveEdit}
								sx={{
									fontWeight: "bold",
									borderRadius: 2,
									textTransform: "none",
								}}
							>
								Save Changes
							</Button>
							<Button
								variant="outlined"
								color="inherit"
								onClick={() => {
									setIsEditing(false);
									setEditTitle(localPost.title);
									setEditContent(localPost.content);
								}}
								sx={{
									fontWeight: "bold",
									borderRadius: 2,
									textTransform: "none",
								}}
							>
								Cancel
							</Button>
						</Box>
					</Box>
				) : (
					<Box 
						onDoubleClick={handleDoubleTap}
						sx={{ 
							position: 'relative', 
							mb: 3, 
							cursor: 'pointer',
							userSelect: 'none' // Prevent text selection on rapid double clicking
						}}
					>
						<Typography
							variant="body1"
							color="text.primary"
							sx={{ whiteSpace: "pre-wrap", pointerEvents: 'none', mb: localPost.tags?.length ? 2 : 0 }}
						>
							{localPost.content}
						</Typography>

                        {localPost.tags && localPost.tags.length > 0 && (
                            <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mb: 1, pointerEvents: 'none' }}>
                                {localPost.tags.map(tag => (
                                    <Chip 
                                        key={tag} 
                                        label={tag} 
                                        size="small" 
                                        sx={{ 
                                            fontSize: '0.7rem', 
                                            fontWeight: 'bold', 
                                            color: 'primary.main', 
                                            bgcolor: 'rgba(0, 102, 51, 0.1)' 
                                        }} 
                                    />
                                ))}
                            </Box>
                        )}

						{images.length === 1 && (
							<>
								<Box 
									onClick={() => { setActiveLightboxIndex(0); setIsLightboxOpen(true); }}
									sx={{ 
										mt: 2, borderRadius: 3, overflow: "hidden", maxHeight: 400, 
										cursor: "pointer", position: "relative",
										'&::after': {
											content: '""', position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
											background: 'rgba(0,0,0,0)', transition: 'background 0.2s',
										},
										'&:hover::after': { background: 'rgba(0,0,0,0.1)' }
									}}
								>
									<img 
										src={images[0]} 
										alt="Post attachment" 
										style={{ width: "100%", height: "100%", objectFit: "cover" }} 
									/>
								</Box>
							</>
						)}

						{images.length > 1 && (
							<Box sx={{
								mt: 2, display: 'flex', overflowX: 'auto', scrollSnapType: 'x mandatory', gap: 1, pb: 1,
								'&::-webkit-scrollbar': { height: 6 },
								'&::-webkit-scrollbar-thumb': { backgroundColor: 'rgba(0,0,0,0.2)', borderRadius: 3 }
							}}>
								{images.map((url, i) => (
									<Box 
										key={i}
										onClick={() => { setActiveLightboxIndex(i); setIsLightboxOpen(true); }}
										sx={{ 
											scrollSnapAlign: 'center', width: '85%', flexShrink: 0,
											borderRadius: 3, overflow: "hidden", maxHeight: 400, cursor: "pointer", position: "relative",
											'&::after': {
												content: '""', position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
												background: 'rgba(0,0,0,0)', transition: 'background 0.2s',
											},
											'&:hover::after': { background: 'rgba(0,0,0,0.1)' }
										}}
									>
										<img 
											src={url} 
											alt={`Post attachment ${i+1}`} 
											style={{ width: "100%", height: "100%", objectFit: "cover" }} 
										/>
									</Box>
								))}
							</Box>
						)}

						{images.length > 0 && (
							<Dialog 
								open={isLightboxOpen} 
								onClose={() => setIsLightboxOpen(false)}
								maxWidth="lg"
								fullWidth
								PaperProps={{ sx: { background: 'transparent', boxShadow: 'none' } }}
							>
								<Box sx={{ position: 'relative', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
									<IconButton 
										onClick={() => setIsLightboxOpen(false)}
										sx={{ position: 'absolute', top: 10, right: 10, color: 'white', bgcolor: 'rgba(0,0,0,0.5)', '&:hover': { bgcolor: 'rgba(0,0,0,0.7)' } }}
									>
										<CloseIcon />
									</IconButton>
									<img 
										src={images[activeLightboxIndex]} 
										alt="Post attachment fullscreen" 
										style={{ maxWidth: '100%', maxHeight: '90vh', objectFit: 'contain', borderRadius: 8 }} 
									/>
								</Box>
							</Dialog>
						)}

						{/* Animated Heart Overlay */}
						{showHeart && (
							<Box
								sx={{
									position: 'absolute',
									top: '50%',
									left: '50%',
									transform: 'translate(-50%, -50%)',
									color: 'secondary.main',
									animation: 'popAndFade 1s ease-out forwards',
									pointerEvents: 'none',
									zIndex: 10,
									display: 'flex',
									justifyContent: 'center',
									alignItems: 'center'
								}}
							>
								<ThumbUpFilled style={{ fontSize: '100px', filter: 'drop-shadow(0 4px 10px rgba(0,0,0,0.3))' }} />
							</Box>
						)}
					</Box>
				)}

				{/* STATS (Likes & Comments counts) */}
				{(localPost.likedBy?.length > 0 || totalCommentsCount > 0) && (
					<Box
						sx={{
							display: "flex",
							justifyContent: "flex-end",
							alignItems: "center",
							gap: 2,
							px: 1,
							mb: 1,
						}}
					>
						{totalCommentsCount > 0 && (
							<Typography
								variant="body2"
								color="text.secondary"
								sx={{
									cursor: "pointer",
									"&:hover": { textDecoration: "underline" },
								}}
								onClick={() => setIsCommentModalOpen(true)}
							>
								{totalCommentsCount}{" "}
								{totalCommentsCount === 1
									? "comment"
									: "comments"}
							</Typography>
						)}
						{localPost.likedBy?.length > 0 && (
							<Box
								onClick={(e) =>
									openLikes(
										e,
										"Post Likes",
										localPost.likedByDetails,
									)
								}
								sx={{
									display: "flex",
									alignItems: "center",
									gap: 0.5,
									cursor: "pointer",
									"&:hover": { textDecoration: "underline" },
								}}
							>
								{(localPost.recentLikerAvatars?.length > 0 || localPost.likedByDetails?.length > 0) && (
									<AvatarGroup max={3} sx={{ mr: 0.5, '& .MuiAvatar-root': { width: 22, height: 22, fontSize: 10, border: '1px solid', borderColor: 'background.paper' } }}>
										{(localPost.likedByDetails || localPost.recentLikerAvatars || []).slice(0, 3).map((liker, i) => {
											const url = typeof liker === 'string' ? liker : liker.profilePic;
											if (!url) return null;
											return <Avatar key={i} src={url} />;
										})}
									</AvatarGroup>
								)}
								<Typography
									variant="body2"
									color="text.secondary"
								>
									{localPost.likedBy.length}
								</Typography>
								<Avatar
									sx={{
										width: 20,
										height: 20,
										bgcolor: "primary.main",
										color: "white",
									}}
								>
									<ThumbUpFilled
										style={{ width: 12, height: 12 }}
									/>
								</Avatar>
							</Box>
						)}
					</Box>
				)}

				<Divider sx={{ mb: 1 }} />

				{/* ACTION BAR */}
				<CardActions
					sx={{
						p: 0,
						justifyContent: "space-between",
						color: "text.secondary",
					}}
				>
					<Box 
						onMouseEnter={() => setShowReactions(true)} 
						onMouseLeave={() => setShowReactions(false)}
						sx={{ position: 'relative' }}
					>
						{/* Floating Reaction Bar */}
						<Collapse in={showReactions} timeout="auto" unmountOnExit sx={{ position: 'absolute', bottom: '100%', left: 0, mb: 1, zIndex: 10 }}>
							<Paper elevation={4} sx={{ display: 'flex', gap: 1, p: 0.5, borderRadius: 10, bgcolor: 'background.paper' }}>
								{['🏸', '🔥', '💯', '👏'].map(emoji => (
									<IconButton 
										key={emoji} 
										onClick={(e) => { e.stopPropagation(); handleLike(); setShowReactions(false); }}
										sx={{ transition: 'transform 0.2s', '&:hover': { transform: 'scale(1.3)' } }}
									>
										<Typography fontSize="1.2rem">{emoji}</Typography>
									</IconButton>
								))}
							</Paper>
						</Collapse>

						<Button
							onClick={handleLike}
							disabled={isLiking}
							color={hasLiked ? "secondary" : "inherit"}
							sx={actionBtnStyle}
						>
							<Box sx={{ mr: { xs: 0.5, sm: 1 }, display: "flex", alignItems: "center" }}>
								{hasLiked ? <ThumbUpFilled /> : <ThumbUpOutline />}
							</Box>
							<Box sx={{ display: { xs: "none", sm: "inline-block" } }}>
								React
							</Box>
						</Button>
					</Box>
					<Button
						onClick={() => setIsCommentModalOpen(true)}
						color="inherit"
						sx={actionBtnStyle}
					>
						<Box
							sx={{
								mr: { xs: 0.5, sm: 1 },
								display: "flex",
								alignItems: "center",
							}}
						>
							<MessageCircleIcon />
						</Box>
						<Box
							sx={{ display: { xs: "none", sm: "inline-block" } }}
						>
							Comment
						</Box>
					</Button>
					<Button
						onClick={(e) => {
							e.stopPropagation();
							const apiUrl = import.meta.env.VITE_API_URL 
								? (import.meta.env.VITE_API_URL.startsWith("http") ? import.meta.env.VITE_API_URL : `https://${import.meta.env.VITE_API_URL}`)
								: window.location.origin;
							const shareUrl = `${apiUrl}/api/forum/share/${localPost._id}`;
							navigator.clipboard.writeText(shareUrl);
							alert("Share link copied to clipboard!");
						}}
						color="inherit"
						sx={actionBtnStyle}
					>
						<Box
							sx={{
								mr: { xs: 0.5, sm: 1 },
								display: "flex",
								alignItems: "center",
							}}
						>
							<ShareIcon />
						</Box>
						<Box
							sx={{ display: { xs: "none", sm: "inline-block" } }}
						>
							Share
						</Box>
					</Button>
				</CardActions>
			</Paper>

			{/* MODALS */}
			<LikesModal
				open={likesModal.open}
				title={likesModal.title}
				list={likesModal.list}
				onClose={() =>
					setLikesModal({ open: false, title: "", list: [] })
				}
			/>

			{/* IMPORTED POST COMMENTS INLINE */}
			<Collapse in={isCommentModalOpen}>
				<PostCommentsInline
					localPost={localPost}
					setLocalPost={setLocalPost}
					currentUser={currentUser}
					highlightId={highlightId}
					openLikes={openLikes}
				/>
			</Collapse>

			{/* IMPORTED DELETE CONFIRMATION */}
			<ConfirmDeleteDialog
				open={deleteConfirmOpen}
				onClose={() => setDeleteConfirmOpen(false)}
				onConfirm={confirmDeletePost}
				itemName="post"
			/>
		</>
	);
}

import React, { useState, useEffect, useRef } from "react";
import {
	Dialog,
	DialogTitle,
	DialogContent,
	Box,
	Typography,
	Button,
	TextField,
	Avatar,
	useTheme,
	useMediaQuery,
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import CommentThread from "./CommentThread"; // FIX: Import the new separated component!

import socket from "../utils/socket";

export default function PostCommentsInline({
	localPost,
	setLocalPost,
	currentUser,
	highlightId,
	openLikes,
}) {
	const navigate = useNavigate();
	const theme = useTheme();
	const fullScreen = useMediaQuery(theme.breakpoints.down("md"));

	const [newReplyText, setNewReplyText] = useState("");
	const [loadingItems, setLoadingItems] = useState({});
	const [typingUsers, setTypingUsers] = useState(new Set());
	const typingTimeoutRef = useRef(null);

	const clickableStyle = {
		cursor: "pointer",
		"&:hover": { textDecoration: "underline", opacity: 0.8 },
		"&:active": { transform: "scale(0.95)" },
	};

	useEffect(() => {
		const onTyping = (data) => {
			if (data.postId === localPost._id && data.userName !== currentUser?.name) {
				setTypingUsers((prev) => {
					const next = new Set(prev);
					next.add(data.userName);
					return next;
				});
			}
		};
		const onStopTyping = (data) => {
			if (data.postId === localPost._id) {
				setTypingUsers((prev) => {
					const next = new Set(prev);
					next.delete(data.userName);
					return next;
				});
			}
		};

		socket.on("commentTyping", onTyping);
		socket.on("commentStopTyping", onStopTyping);
		return () => {
			socket.off("commentTyping", onTyping);
			socket.off("commentStopTyping", onStopTyping);
		};
	}, [localPost._id, currentUser]);

	useEffect(() => {
		if (open && highlightId) {
			setTimeout(() => {
				const targetElement = document.getElementById(
					`comment-${highlightId}`,
				);
				if (targetElement)
					targetElement.scrollIntoView({
						behavior: "smooth",
						block: "center",
					});
			}, 300);
		}
	}, [open, highlightId]);

	// Shared utility to handle @mentions and breaking long strings
	const renderContentWithTags = (content) => {
		if (!content) return null;
		const userMap = new Map();
		if (localPost.authorName)
			userMap.set(localPost.authorName, localPost.authorId);
		localPost.comments?.forEach((c) => {
			userMap.set(c.authorName, c.authorId);
			c.replies?.forEach((r) => userMap.set(r.authorName, r.authorId));
		});

		if (userMap.size === 0)
			return (
				<Typography
					variant="body2"
					sx={{
						fontSize: "0.875rem",
						mt: 0.5,
						whiteSpace: "pre-wrap",
						wordBreak: "break-word",
						overflowWrap: "anywhere",
					}}
				>
					{content}
				</Typography>
			);

		const names = Array.from(userMap.keys())
			.sort((a, b) => b.length - a.length)
			.map((n) => n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
		const regex = new RegExp(`(@(?:${names.join("|")}))`, "g");
		const parts = content.split(regex);

		return (
			<Typography
				variant="body2"
				sx={{
					fontSize: "0.875rem",
					mt: 0.5,
					whiteSpace: "pre-wrap",
					wordBreak: "break-word",
					overflowWrap: "anywhere",
				}}
			>
				{parts.map((part, i) => {
					if (part.startsWith("@")) {
						const name = part.substring(1);
						const id = userMap.get(name);
						if (id)
							return (
								<Box
									key={i}
									component="span"
									onClick={(e) => {
										e.stopPropagation();
										navigate(`/profile/${id}`);
									}}
									sx={{
										color: "primary.main",
										fontWeight: "bold",
										backgroundColor:
											"rgba(0, 102, 51, 0.12)",
										px: 0.6,
										py: 0.2,
										borderRadius: 1.5,
										cursor: "pointer",
										display: "inline-block",
										"&:hover": {
											textDecoration: "underline",
											backgroundColor:
												"rgba(0, 102, 51, 0.25)",
										},
									}}
								>
									{part}
								</Box>
							);
					}
					return <span key={i}>{part}</span>;
				})}
			</Typography>
		);
	};

	const apiCall = async (
		endpoint,
		method,
		bodyData,
		skipStateUpdate = false,
	) => {
		try {
			const res = await fetch(
				`${import.meta.env.VITE_API_URL}${endpoint}`,
				{
					method,
					headers: {
						"Content-Type": "application/json",
						Authorization: `Bearer ${localStorage.getItem("token")}`,
					},
					body: JSON.stringify(bodyData),
				},
			);
			if (res.ok && !skipStateUpdate) setLocalPost(await res.json());
		} catch (err) {
			console.error(err);
		}
	};

	const handleToggleLike = async (endpoint, itemId) => {
		if (!currentUser) return alert("You must be logged in!");
		if (loadingItems[itemId]) return;

		setLoadingItems((prev) => ({ ...prev, [itemId]: true }));
		await apiCall(endpoint, "PUT", {
			userId: currentUser.id,
			userName: currentUser.name,
		});
		setLoadingItems((prev) => ({ ...prev, [itemId]: false }));
	};

	const handlePostMainComment = () => {
		if (!newReplyText.trim() || !currentUser) return;
		apiCall(`/api/forum/${localPost._id}/comments`, "POST", {
			authorId: currentUser.id,
			authorName: currentUser.name,
			content: newReplyText.trim(),
		});
		setNewReplyText("");
		socket.emit("commentStopTyping", { postId: localPost._id, userName: currentUser.name });
	};

	const handleTyping = (e) => {
		setNewReplyText(e.target.value);
		if (currentUser) {
			socket.emit("commentTyping", { postId: localPost._id, userName: currentUser.name });
			clearTimeout(typingTimeoutRef.current);
			typingTimeoutRef.current = setTimeout(() => {
				socket.emit("commentStopTyping", { postId: localPost._id, userName: currentUser.name });
			}, 2000);
		}
	};

	const formatTime = (dateString) =>
		dateString
			? new Date(dateString).toLocaleDateString("en-US", {
					month: "short",
					day: "numeric",
					hour: "numeric",
					minute: "2-digit",
				})
			: "Just now";

	return (
		<Box sx={{ borderTop: "1px solid", borderColor: "divider", mt: 2, pt: 2 }}>
			

			<Box>
				

				<Box sx={{ p: { xs: 1, sm: 2 } }}>
					{!localPost.comments?.length ? (
						<Typography
							variant="body2"
							color="text.secondary"
							sx={{ textAlign: "center", mt: 2 }}
						>
							No comments yet. Be the first to reply!
						</Typography>
					) : (
						<Box
							sx={{
								display: "flex",
								flexDirection: "column",
								gap: 2,
							}}
						>
							{/* FIX: Delegate the complex mapping to the new CommentThread component! */}
							{localPost.comments.map((comment) => (
								<CommentThread
									key={comment._id}
									comment={comment}
									localPost={localPost}
									currentUser={currentUser}
									highlightId={highlightId}
									openLikes={openLikes}
									handleToggleLike={handleToggleLike}
									apiCall={apiCall}
									formatTime={formatTime}
									renderContentWithTags={
										renderContentWithTags
									}
									clickableStyle={clickableStyle}
								/>
							))}
						</Box>
					)}
				</Box>
			</Box>

			{/* TYPING INDICATOR */}
			{typingUsers.size > 0 && (
				<Typography variant="caption" color="text.secondary" sx={{ ml: 6, fontStyle: "italic", mb: 0.5, display: "block" }}>
					{Array.from(typingUsers).join(", ")} {typingUsers.size === 1 ? "is" : "are"} typing...
				</Typography>
			)}

			{/* MAIN POST COMMENT INPUT */}
			<Box
				sx={{
					p: 1.5,
					backgroundColor: "background.paper",
					borderTop: "1px solid",
					borderColor: "divider",
					display: "flex",
					gap: 1,
					alignItems: "flex-end",
				}}
			>
				<Avatar
					src={currentUser?.profilePic}
					sx={{
						width: 32,
						height: 32,
						bgcolor: "primary.main",
						mb: 0.5,
					}}
				>
					{!currentUser?.profilePic && currentUser?.name
						? currentUser.name?.charAt(0).toUpperCase()
						: "?"}
				</Avatar>
				<TextField
					fullWidth
					size="small"
					multiline
					maxRows={4}
					placeholder={
						currentUser ? "Write a comment..." : "Login to comment"
					}
					value={newReplyText}
					onChange={handleTyping}
					onKeyDown={(e) => {
						if (e.key === "Enter" && !e.shiftKey) {
							e.preventDefault();
							handlePostMainComment();
						}
					}}
					disabled={!currentUser}
					sx={{
						"& .MuiOutlinedInput-root": {
							borderRadius: "20px",
							backgroundColor: "action.hover",
							py: 1,
							px: 2,
						},
					}}
				/>
				<Button
					variant="contained"
					onClick={handlePostMainComment}
					disabled={!newReplyText.trim() || !currentUser}
					sx={{
						borderRadius: 5,
						fontWeight: "bold",
						textTransform: "none",
						mb: 0.5,
						transition: "all 0.1s",
						"&:active": { transform: "scale(0.95)" },
					}}
				>
					Post
				</Button>
			</Box>
		</Box>
	);
}

