import React from "react";
import { useState } from "react";
import {
	Box,
	Typography,
	Button,
	TextField,
	Avatar,
	IconButton,
	Menu,
	MenuItem,
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import { MoreVertIcon } from "../Icons";

export default function CommentBubble({
	comment,
	localPostId,
	currentUser,
	openLikes,
