import React, { useState, useRef } from "react";
import ReactCrop, { centerCrop, makeAspectCrop } from "react-image-crop";
import "react-image-crop/dist/ReactCrop.css";
import {
	Dialog,
	DialogTitle,
	DialogContent,
	DialogActions,
	Button,
	Box,
} from "@mui/material";
import getCroppedImg from "../../utils/cropImage";

function centerAspectCrop(mediaWidth, mediaHeight, aspect) {
	return centerCrop(
		makeAspectCrop(
			{
				unit: "%",
				width: 90,
			},
			aspect,
			mediaWidth,
			mediaHeight
		),
		mediaWidth,
		mediaHeight
	);
}

export default function ImageCropModal({
	open,
	imageSrc,
	onClose,
	onCropComplete,
	aspectRatio,
	title = "Crop Image"
}) {
	const [crop, setCrop] = useState();
	const [completedCrop, setCompletedCrop] = useState(null);
	const imgRef = useRef(null);

	const onImageLoad = (e) => {
		const { width, height } = e.currentTarget;
		if (aspectRatio) {
			setCrop(centerAspectCrop(width, height, aspectRatio));
		}
	};

	const handleSave = async () => {
		if (!completedCrop || !imgRef.current) return;

		const image = imgRef.current;
		const scaleX = image.naturalWidth / image.width;
		const scaleY = image.naturalHeight / image.height;

		const pixelCrop = {
			x: completedCrop.x * scaleX,
			y: completedCrop.y * scaleY,
			width: completedCrop.width * scaleX,
			height: completedCrop.height * scaleY,
		};

		try {
			const croppedImageBlob = await getCroppedImg(imageSrc, pixelCrop);
			onCropComplete(croppedImageBlob);
		} catch (e) {
			console.error(e);
		}
	};

	return (
		<Dialog 
			open={open} 
			onClose={onClose} 
			maxWidth="md" 
			fullWidth
			PaperProps={{
				sx: {
					bgcolor: 'background.paper',
					borderRadius: 4,
					overflow: 'hidden'
				}
			}}
		>
			<DialogTitle sx={{ fontWeight: "900", textAlign: "center", py: 3 }}>
				{title}
			</DialogTitle>
			<DialogContent sx={{ 
				display: "flex", 
				justifyContent: "center", 
				alignItems: "center", 
				bgcolor: "background.default", 
				minHeight: 400,
				p: 0,
				position: "relative"
			}}>
				{imageSrc && (
					<ReactCrop
						crop={crop}
						onChange={(_, percentCrop) => setCrop(percentCrop)}
						onComplete={(c) => setCompletedCrop(c)}
						aspect={aspectRatio}
						ruleOfThirds
						style={{ maxWidth: '100%', maxHeight: '60vh' }}
					>
						<img
							ref={imgRef}
							src={imageSrc}
							onLoad={onImageLoad}
							style={{ maxHeight: "60vh", maxWidth: "100%", display: "block", objectFit: "contain" }}
							alt="Crop"
						/>
					</ReactCrop>
				)}
			</DialogContent>
			<DialogActions sx={{ p: 3, display: "flex", justifyContent: "space-between", bgcolor: "background.paper" }}>
				<Button 
					onClick={onClose} 
					sx={{ 
						borderRadius: 3, 
						textTransform: "none",
						fontWeight: "bold",
						color: "text.secondary",
						px: 3
					}}
				>
					Cancel
				</Button>
				<Button 
					onClick={handleSave} 
					variant="contained" 
					color="primary" 
					sx={{ 
						borderRadius: 3, 
						textTransform: "none", 
						fontWeight: "bold",
						px: 4,
						py: 1
					}}
					disabled={!completedCrop?.width || !completedCrop?.height}
				>
					Save Photo
				</Button>
			</DialogActions>
		</Dialog>
	);
}

// client/src/context/AuthContext.jsx
import React, { createContext, useContext, useState, useEffect } from "react";
import apiFetch from "../utils/api";
import { toast } from "react-hot-toast";

export const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
	const [user, setUser] = useState(() => {
		try {
			const saved = localStorage.getItem("user");
			return saved ? JSON.parse(saved) : null;
		} catch {
			return null;
		}
	});
	const setToastMessage = React.useCallback((msg) => {
		if (msg) toast.success(msg, {
			style: {
				borderRadius: '10px',
				background: '#333',
				color: '#fff',
			},
		});
	}, []);

	useEffect(() => {
		if (localStorage.getItem("justLoggedOut")) {
			setToastMessage("You have been successfully logged out.");
			localStorage.removeItem("justLoggedOut");
		}
	}, []);

	const login = React.useCallback((userData, accessToken, refreshToken, customMessage = null) => {
		localStorage.setItem("accessToken", accessToken);
		localStorage.setItem("refreshToken", refreshToken);
		localStorage.setItem("user", JSON.stringify(userData));
		setUser(userData);
		setToastMessage(customMessage || `Welcome back, ${userData.name}!`);
	}, [setToastMessage]);

	const logout = React.useCallback(async () => {
		const refreshToken = localStorage.getItem("refreshToken");
		if (refreshToken) {
			await apiFetch("/api/auth/logout", {
				method: "POST",
				body: JSON.stringify({ refreshToken }),
			}).catch(console.error);
		}
		localStorage.removeItem("accessToken");
		localStorage.removeItem("refreshToken");
		localStorage.removeItem("user");
		setUser(null);
		localStorage.setItem("justLoggedOut", "true");
		window.location.href = "/";
	}, []);

	const updateUser = React.useCallback((updatedUser) => {
		localStorage.setItem("user", JSON.stringify(updatedUser));
		setUser(updatedUser);
	}, []);

	const contextValue = React.useMemo(() => ({
		user,
		setUser,
		login,
		logout,
		updateUser,
		toastMessage: null,
		setToastMessage,
	}), [user, setToastMessage, login, logout, updateUser]);

	return (
		<AuthContext.Provider value={contextValue}>
			{children}
		</AuthContext.Provider>
	);
};

export const useAuth = () => {
	const context = useContext(AuthContext);
	if (!context) {
		throw new Error("useAuth must be used within an AuthProvider");
	}
	return context;
};

