// client/src/pages/Admin.jsx
import { useState, useEffect } from "react";
import {
	Container,
	Typography,
	Box,
	Paper,
	Table,
	TableBody,
	TableCell,
	TableContainer,
	TableHead,
	TableRow,
	Button,
	Chip,
	Dialog,
	DialogTitle,
	DialogContent,
	DialogActions as MuiDialogActions,
} from "@mui/material";

import apiFetch from "../utils/api";

// Sleek Trash Icon
const TrashIcon = () => (
	<svg
		width="20"
		height="20"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<polyline points="3 6 5 6 21 6"></polyline>
		<path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
	</svg>
);

export default function Admin() {
	const [users, setUsers] = useState([]);
	const [posts, setPosts] = useState([]);
	const [flaggedPosts, setFlaggedPosts] = useState([]);
	const [flaggedMessages, setFlaggedMessages] = useState([]);
	const [allMessages, setAllMessages] = useState([]);

	// NEW: Centralized Sleek Delete Confirmation State
	const [deleteConfirm, setDeleteConfirm] = useState({
		open: false,
		type: "",
		id: null,
	});

	const fetchAdminData = async () => {
		try {
			const [userRes, postRes, flaggedRes, flaggedMsgsRes, allMsgsRes] = await Promise.all([
				apiFetch(`/api/admin/users`),
				apiFetch(`/api/admin/posts`),
				apiFetch(`/api/admin/flagged`),
				apiFetch(`/api/admin/flagged-messages`),
				apiFetch(`/api/admin/all-messages`),
			]);
			setUsers(await userRes.json());
			setPosts(await postRes.json());
			setFlaggedPosts(await flaggedRes.json());
			setFlaggedMessages(await flaggedMsgsRes.json());
			setAllMessages(await allMsgsRes.json());
		} catch (err) {
			console.error("Failed to fetch admin data", err);
		}
	};

	useEffect(() => {
		fetchAdminData();
	}, []);

	const handleApprovePost = async (id) => {
		try {
			const res = await apiFetch(`/api/admin/flagged/${id}/approve`, { method: "PUT" });
			const { post } = await res.json();
			setFlaggedPosts(flaggedPosts.filter((p) => p._id !== id));
			setPosts([post, ...posts]);
		} catch (err) {
			console.error(err);
		}
	};

	const handleApproveMessage = async (id) => {
		try {
			await apiFetch(`/api/admin/messages/${id}/dismiss`, { method: "PUT" });
			setFlaggedMessages(flaggedMessages.filter((m) => m._id !== id));
		} catch (err) {
			console.error(err);
		}
	};

	// NEW: Execution function that runs from the Modal
	const executeDelete = async () => {
		const { type, id } = deleteConfirm;
		if (!id) return;

		try {
			if (type === "user") {
				await apiFetch(`/api/admin/users/${id}`, { method: "DELETE" });
				setUsers(users.filter((u) => u._id !== id));
			} else if (type === "post") {
				await apiFetch(`/api/admin/posts/${id}`, { method: "DELETE" });
				setPosts(posts.filter((p) => p._id !== id));
			} else if (type === "spam") {
				await apiFetch(`/api/admin/posts/${id}`, { method: "DELETE" });
				setFlaggedPosts(flaggedPosts.filter((p) => p._id !== id));
			} else if (type === "message") {
				await apiFetch(`/api/admin/messages/${id}`, { method: "DELETE" });
				setFlaggedMessages(flaggedMessages.filter((m) => m._id !== id));
				setAllMessages(allMessages.filter((m) => m._id !== id));
			}
		} catch (err) {
			console.error(err);
		}

		setDeleteConfirm({ open: false, type: "", id: null }); // Close modal
	};

	const promptDelete = (type, id) =>
		setDeleteConfirm({ open: true, type, id });

	return (
		<Container
			maxWidth="lg"
			sx={{ mt: { xs: 2, md: 5 }, pb: 10, px: { xs: 1, sm: 2, md: 3 } }}
		>
			<Box sx={{ mb: { xs: 3, md: 5 }, textAlign: "center" }}>
				<Typography
					variant="h3"
					color="error.main"
					fontWeight="900"
					gutterBottom
					sx={{ fontSize: { xs: "2.2rem", md: "3rem" } }}
				>
					Admin Tab
				</Typography>
				<Typography variant="h6" color="text.secondary">
					Platform Administration Hub
				</Typography>
			</Box>

			{/* MODERATION QUEUE */}
			<Typography
				variant="h5"
				color="error.main"
				fontWeight="900"
				sx={{ mb: 2, ml: 1 }}
			>
				🚨 Moderation Queue (Spam)
			</Typography>

			{flaggedPosts.length === 0 ? (
				<Paper
					elevation={0}
					sx={{
						p: 4,
						mb: 6,
						textAlign: "center",
						borderRadius: 3,
						border: "1px solid", borderColor: "divider",
					}}
				>
					<Typography variant="h6" color="text.secondary">
						No spam detected! The forum is clean.
					</Typography>
				</Paper>
			) : (
				<Box sx={{ mb: 6 }}>
					{flaggedPosts.map((post) => (
						<Paper
							key={post._id}
							elevation={0}
							sx={{
								p: 3,
								mb: 2,
								borderRadius: 3,
								border: "2px solid #ffcccc",
								backgroundColor: "#fff5f5",
							}}
						>
							<Box
								sx={{
									display: "flex",
									justifyContent: "space-between",
									mb: 1,
								}}
							>
								<Typography
									variant="subtitle1"
									fontWeight="bold"
								>
									{post.authorName}
								</Typography>
								<Typography
									variant="caption"
									color="error.main"
									fontWeight="bold"
								>
									Flagged on{" "}
									{new Date(post.timestamp).toLocaleString()}
								</Typography>
							</Box>
							<Box sx={{ mb: 2 }}>
								<Chip 
									label={`Toxicity Score: ${post.toxicityScore || 0}`} 
									color={post.toxicityScore < -4 ? "error" : "warning"} 
									size="small" 
									sx={{ fontWeight: "bold" }} 
								/>
							</Box>
							<Typography
								variant="h6"
								fontWeight="bold"
								sx={{ mb: 1 }}
							>
								{post.title}
							</Typography>
							<Typography
								variant="body2"
								sx={{
									mb: 3,
									whiteSpace: "pre-wrap",
									p: 2,
									backgroundColor: "background.paper",
									borderRadius: 2,
									border: "1px dashed #ffcccc",
								}}
							>
								{post.content}
							</Typography>
							<Box sx={{ display: "flex", gap: 2 }}>
								<Button
									variant="contained"
									color="error"
									onClick={() =>
										promptDelete("spam", post._id)
									}
									sx={{
										fontWeight: "bold",
										textTransform: "none",
									}}
								>
									Delete Spam
								</Button>
								<Button
									variant="outlined"
									color="success"
									onClick={() => handleApprovePost(post._id)}
									sx={{
										fontWeight: "bold",
										bgcolor: "background.paper",
										textTransform: "none",
									}}
								>
									Approve (Not Spam)
								</Button>
							</Box>
						</Paper>
					))}
				</Box>
			)}

			{/* FLAGGED MESSAGES QUEUE */}
			<Typography
				variant="h5"
				color="error.main"
				fontWeight="900"
				sx={{ mb: 2, ml: 1 }}
			>
				🕵️ Reported Private Messages
			</Typography>

			{flaggedMessages.length === 0 ? (
				<Paper
					elevation={0}
					sx={{
						p: 4,
						mb: 6,
						textAlign: "center",
						borderRadius: 3,
						border: "1px solid", borderColor: "divider",
					}}
				>
					<Typography variant="h6" color="text.secondary">
						No reported messages! Chats are safe.
					</Typography>
				</Paper>
			) : (
				<Box sx={{ mb: 6 }}>
					{flaggedMessages.map((msg) => (
						<Paper
							key={msg._id}
							elevation={0}
							sx={{
								p: 3,
								mb: 2,
								borderRadius: 3,
								border: "2px solid #ff9999",
								backgroundColor: "#fff0f0",
							}}
						>
							<Box
								sx={{
									display: "flex",
									justifyContent: "space-between",
									mb: 1,
								}}
							>
								<Typography variant="subtitle1" fontWeight="bold">
									{msg.sender?.name} → {msg.receiver?.name}
								</Typography>
								<Typography variant="caption" color="error.main" fontWeight="bold">
									{msg.flagReason}
								</Typography>
							</Box>
							<Box sx={{ mb: 2 }}>
								<Chip 
									label={`Toxicity Score: ${msg.toxicityScore || 0}`} 
									color={msg.toxicityScore < -4 ? "error" : "warning"} 
									size="small" 
									sx={{ fontWeight: "bold" }} 
								/>
							</Box>
							<Typography
								variant="body2"
								sx={{
									mb: 3,
									whiteSpace: "pre-wrap",
									p: 2,
									backgroundColor: "background.paper",
									borderRadius: 2,
									border: "1px dashed #ff9999",
								}}
							>
								{msg.content}
							</Typography>
							<Box sx={{ display: "flex", gap: 2 }}>
								<Button
									variant="contained"
									color="error"
									onClick={() => promptDelete("message", msg._id)}
									sx={{ fontWeight: "bold", textTransform: "none" }}
								>
									Censor Message
								</Button>
								<Button
									variant="outlined"
									color="success"
									onClick={() => handleApproveMessage(msg._id)}
									sx={{ fontWeight: "bold", bgcolor: "background.paper", textTransform: "none" }}
								>
									Dismiss Flag
								</Button>
							</Box>
						</Paper>
					))}
				</Box>
			)}

			{/* GLOBAL CHAT LOGS */}
			<Typography
				variant="h5"
				color="primary"
				fontWeight="bold"
				sx={{ mb: 2, ml: 1 }}
			>
				🌐 Global Chat Logs ({allMessages.length})
			</Typography>
			<TableContainer
				component={Paper}
				elevation={0}
				sx={{
					mb: 6,
					border: "1px solid", borderColor: "divider",
					borderRadius: 3,
					width: "100%",
					overflowX: "auto",
					maxHeight: 400,
				}}
			>
				<Table stickyHeader sx={{ minWidth: 600 }}>
					<TableHead>
						<TableRow>
							<TableCell sx={{ fontWeight: "bold", backgroundColor: "#f4f6f8" }}>Date</TableCell>
							<TableCell sx={{ fontWeight: "bold", backgroundColor: "#f4f6f8" }}>Sender</TableCell>
							<TableCell sx={{ fontWeight: "bold", backgroundColor: "#f4f6f8" }}>Receiver</TableCell>
							<TableCell sx={{ fontWeight: "bold", backgroundColor: "#f4f6f8" }}>Message</TableCell>
							<TableCell align="right" sx={{ fontWeight: "bold", backgroundColor: "#f4f6f8" }}>Actions</TableCell>
						</TableRow>
					</TableHead>
					<TableBody>
						{allMessages.map((msg) => (
							<TableRow key={msg._id} hover>
								<TableCell sx={{ whiteSpace: "nowrap" }}>
									{new Date(msg.timestamp).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
								</TableCell>
								<TableCell sx={{ whiteSpace: "nowrap" }}>{msg.sender?.name}</TableCell>
								<TableCell sx={{ whiteSpace: "nowrap" }}>{msg.receiver?.name}</TableCell>
								<TableCell sx={{ maxWidth: 250, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
									{msg.isDeletedByAdmin ? (
										<Typography variant="body2" sx={{ fontStyle: 'italic', color: 'error.main' }}>[Censored]</Typography>
									) : (
										msg.content
									)}
								</TableCell>
								<TableCell align="right" sx={{ whiteSpace: "nowrap" }}>
									<Button
										variant="outlined"
										color="error"
										size="small"
										onClick={() => promptDelete("message", msg._id)}
										disabled={msg.isDeletedByAdmin}
										sx={{ textTransform: "none", fontWeight: "bold" }}
									>
										Censor
									</Button>
								</TableCell>
							</TableRow>
						))}
					</TableBody>
				</Table>
			</TableContainer>

			{/* USERS TABLE */}
			<Typography
				variant="h5"
				color="primary"
				fontWeight="bold"
				sx={{ mb: 2, ml: 1 }}
			>
				Manage Users ({users.length})
			</Typography>
			<TableContainer
				component={Paper}
				elevation={0}
				sx={{
					mb: 6,
					border: "1px solid", borderColor: "divider",
					borderRadius: 3,
					width: "100%",
					overflowX: "auto",
				}}
			>
				<Table sx={{ minWidth: 500 }}>
					<TableHead sx={{ backgroundColor: "#f4f6f8" }}>
						<TableRow>
							<TableCell
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Name
							</TableCell>
							<TableCell
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Email
							</TableCell>
							<TableCell
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Role
							</TableCell>
							<TableCell
								align="right"
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Actions
							</TableCell>
						</TableRow>
					</TableHead>
					<TableBody>
						{users.map((u) => (
							<TableRow key={u._id}>
								<TableCell sx={{ whiteSpace: "nowrap" }}>
									{u.name}
								</TableCell>
								<TableCell sx={{ whiteSpace: "nowrap" }}>
									{u.email}
								</TableCell>
								<TableCell sx={{ whiteSpace: "nowrap" }}>
									<Chip
										label={u.role.toUpperCase()}
										color={
											u.role === "admin"
												? "error"
												: "default"
										}
										size="small"
										sx={{ fontWeight: "bold" }}
									/>
								</TableCell>
								<TableCell
									align="right"
									sx={{ whiteSpace: "nowrap" }}
								>
									<Button
										variant="outlined"
										color="error"
										size="small"
										onClick={() =>
											promptDelete("user", u._id)
										}
										disabled={u.role === "admin"}
										sx={{
											textTransform: "none",
											fontWeight: "bold",
										}}
									>
										Delete
									</Button>
								</TableCell>
							</TableRow>
						))}
					</TableBody>
				</Table>
			</TableContainer>

			{/* POSTS TABLE */}
			<Typography
				variant="h5"
				color="primary"
				fontWeight="bold"
				sx={{ mb: 2, ml: 1 }}
			>
				Manage Posts ({posts.length})
			</Typography>
			<TableContainer
				component={Paper}
				elevation={0}
				sx={{
					border: "1px solid", borderColor: "divider",
					borderRadius: 3,
					width: "100%",
					overflowX: "auto",
				}}
			>
				<Table sx={{ minWidth: 600 }}>
					<TableHead sx={{ backgroundColor: "#f4f6f8" }}>
						<TableRow>
							<TableCell
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Title
							</TableCell>
							<TableCell
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Author
							</TableCell>
							<TableCell
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Date Target
							</TableCell>
							<TableCell
								align="right"
								sx={{
									fontWeight: "bold",
									whiteSpace: "nowrap",
								}}
							>
								Actions
							</TableCell>
						</TableRow>
					</TableHead>
					<TableBody>
						{posts.map((p) => (
							<TableRow key={p._id}>
								<TableCell
									sx={{
										maxWidth: { xs: 150, sm: 250 },
										whiteSpace: "nowrap",
										overflow: "hidden",
										textOverflow: "ellipsis",
									}}
								>
									{p.title}
								</TableCell>
								<TableCell sx={{ whiteSpace: "nowrap" }}>
									{p.authorName}
								</TableCell>
								<TableCell sx={{ whiteSpace: "nowrap" }}>
									{p.targetDate}
								</TableCell>
								<TableCell
									align="right"
									sx={{ whiteSpace: "nowrap" }}
								>
									<Button
										variant="outlined"
										color="error"
										size="small"
										onClick={() =>
											promptDelete("post", p._id)
										}
										sx={{
											textTransform: "none",
											fontWeight: "bold",
										}}
									>
										Delete
									</Button>
								</TableCell>
							</TableRow>
						))}
					</TableBody>
				</Table>
			</TableContainer>

			{/* SLEEK DELETE CONFIRMATION DIALOG */}
			<Dialog
				open={deleteConfirm.open}
				onClose={() =>
					setDeleteConfirm({ open: false, type: "", id: null })
				}
				PaperProps={{ sx: { borderRadius: 3, p: 1 } }}
			>
				<DialogTitle
					sx={{
						fontWeight: "bold",
						display: "flex",
						alignItems: "center",
						gap: 1,
						color: "error.main",
					}}
				>
					<TrashIcon /> Confirm Deletion
				</DialogTitle>
				<DialogContent>
					<Typography>
						Are you sure you want to permanently delete this{" "}
						{deleteConfirm.type === "user"
							? "user"
							: deleteConfirm.type === "spam"
								? "spam post"
								: deleteConfirm.type === "message"
									? "private message"
									: "post"}
						? This action cannot be undone.
					</Typography>
				</DialogContent>
				<MuiDialogActions sx={{ px: 3, pb: 2 }}>
					<Button
						onClick={() =>
							setDeleteConfirm({
								open: false,
								type: "",
								id: null,
							})
						}
						color="inherit"
						sx={{ fontWeight: "bold", textTransform: "none" }}
					>
						Cancel
					</Button>
					<Button
						onClick={executeDelete}
						variant="contained"
						color="error"
						sx={{
							fontWeight: "bold",
							textTransform: "none",
							borderRadius: 2,
						}}
					>
						Delete
					</Button>
				</MuiDialogActions>
			</Dialog>
		</Container>
	);
}

// client/src/pages/Dashboard.jsx
import { useState, useEffect } from "react";
import {
	Typography,
	Box,
	Paper,
	Button,
	Grid,
	Avatar,
	CircularProgress,
	Chip,
	Divider,
	TextField,
	IconButton,
	Dialog,
	DialogTitle,
	DialogContent,
	DialogActions as MuiDialogActions,
	Skeleton,
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import apiFetch from "../utils/api";
import { getOptimizedAvatar } from "../utils/image";
import { io } from "socket.io-client";

const socket = io(`${import.meta.env.VITE_API_URL}`);

// Sleek SVG Icons

const MegaphoneIcon = () => (
	<svg
		width="20"
		height="20"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon>
		<path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07"></path>
	</svg>
);

const PinIcon = () => (
	<svg
		width="16"
		height="16"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path>
		<circle cx="12" cy="10" r="3"></circle>
	</svg>
);
const TrashIcon = () => (
	<svg
		width="16"
		height="16"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<polyline points="3 6 5 6 21 6"></polyline>
		<path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
	</svg>
);
const TrashIconLarge = () => (
	<svg
		width="20"
		height="20"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<polyline points="3 6 5 6 21 6"></polyline>
		<path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
	</svg>
);

export default function Dashboard() {
		const currentUser = JSON.parse(localStorage.getItem("user"));

	const [status, setStatus] = useState(null);
	const [schedule, setSchedule] = useState(null);
	const [announcements, setAnnouncements] = useState([]);
		const [loading, setLoading] = useState(true);
	
	// Infinite Scroll State
	


	const [newUpdateText, setNewUpdateText] = useState("");
	const [isPosting, setIsPosting] = useState(false);
	const [deleteUpdateId, setDeleteUpdateId] = useState(null);

	// Load Initial Dashboard Data
	useEffect(() => {
		const fetchDashboardData = async () => {
			try {
				const [statusRes, announcementsRes] = await Promise.all([
					apiFetch(`/api/status`),
					apiFetch(`/api/announcements`)
				]);

				if (statusRes.ok) setStatus((await statusRes.json()).message);
				if (announcementsRes.ok) setAnnouncements(await announcementsRes.json());

				// Fetch Java Court Schedule
				let apiUrl = import.meta.env.VITE_TOURNAMENT_API_URL;
				const isLocalNetwork = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.hostname.startsWith('192.168.') || window.location.hostname.startsWith('10.');
				
				if (!apiUrl) {
					apiUrl = isLocalNetwork ? `http://${window.location.hostname}:8081` : null;
				} else if (!apiUrl.startsWith("http")) {
					apiUrl = "https://" + apiUrl;
				}

				if (apiUrl) {
					try {
						const courtRes = await fetch(`${apiUrl}/api/v1/courts/status`);
						if (courtRes.ok) {
							setSchedule(await courtRes.json());
							return;
						}
					} catch (e) {
						console.error("Failed to fetch RAC schedule", e);
						console.log("Java backend unreachable, using fallback...");
					}
				}

				// FALLBACK: Mock Weekly Schedule based on User's Screenshot
				const now = new Date();
				const getNextDay = (dayOfWeek) => {
					const d = new Date(now);
					d.setDate(d.getDate() + ((dayOfWeek + 7 - d.getDay()) % 7));
					return d;
				};

				const fallbackSchedule = {
					facilityName: "RAC Linn Gym Court B",
					timeSlots: [
						{ startTime: getNextDay(1).setHours(17, 0, 0), endTime: getNextDay(1).setHours(19, 0, 0), status: 'CLUB_ONLY', eventName: 'Club Badminton Practice' },
						{ startTime: getNextDay(2).setHours(16, 30, 0), endTime: getNextDay(2).setHours(18, 30, 0), status: 'DEDICATED', eventName: 'Dedicated Drop In Badminton ct. B' },
						{ startTime: getNextDay(4).setHours(19, 0, 0), endTime: getNextDay(4).setHours(21, 0, 0), status: 'DEDICATED', eventName: 'Dedicated Drop in Badminton...' },
						{ startTime: getNextDay(6).setHours(18, 0, 0), endTime: getNextDay(6).setHours(20, 0, 0), status: 'CLUB_ONLY', eventName: 'Club Badminton Practice' }
					]
				};
				// Sort chronologically
				fallbackSchedule.timeSlots.sort((a, b) => a.startTime - b.startTime);
				setSchedule(fallbackSchedule);

			} catch (err) {
				console.error("Failed to load dashboard data", err);
			} finally {
				setLoading(false);
			}
		};

		fetchDashboardData();

		const handleNewAnnouncement = (newAnn) =>
			setAnnouncements((prev) => [newAnn, ...prev]);
		const handleDeletedAnnouncement = (deletedId) =>
			setAnnouncements((prev) => prev.filter((a) => a._id !== deletedId));


		socket.on("announcementCreated", handleNewAnnouncement);
		socket.on("announcementDeleted", handleDeletedAnnouncement);

		return () => {
			socket.off("announcementCreated", handleNewAnnouncement);
			socket.off("announcementDeleted", handleDeletedAnnouncement);
		};
	}, []);


	const handlePostUpdate = async () => {
		if (!newUpdateText.trim() || currentUser?.role !== "admin") return;
		setIsPosting(true);
		try {
			await apiFetch(`/api/announcements`, {
				method: "POST",
				body: JSON.stringify({
					content: newUpdateText,
					authorName: currentUser.name,
					authorId: currentUser.id,
					role: currentUser.role,
				}),
			});
			setNewUpdateText("");
		} catch (err) {
			console.error("Failed to post update", err);
		} finally {
			setIsPosting(false);
		}
	};

	const confirmDeleteUpdate = async () => {
		if (!deleteUpdateId) return;
		try {
			await apiFetch(
				`/api/announcements/${deleteUpdateId}?role=${currentUser.role}`,
				{
					method: "DELETE",
				}
			);
		} catch (err) {
			console.error("Failed to delete update", err);
		}
		setDeleteUpdateId(null);
	};

	const formatTime = (dateString) => {
		if (!dateString) return "";
		return new Date(dateString).toLocaleDateString("en-US", {
			month: "short",
			day: "numeric",
			hour: "numeric",
			minute: "2-digit",
		});
	};

	return (
		<Box sx={{ pb: 10 }}>
			<style>
				{`
					@keyframes pulseRed { 0% { box-shadow: 0 0 0 0 rgba(255, 68, 68, 0.7); } 70% { box-shadow: 0 0 0 10px rgba(255, 68, 68, 0); } 100% { box-shadow: 0 0 0 0 rgba(255, 68, 68, 0); } }
					@keyframes pulseGreen { 0% { box-shadow: 0 0 0 0 rgba(0, 230, 118, 0.7); } 70% { box-shadow: 0 0 0 10px rgba(0, 230, 118, 0); } 100% { box-shadow: 0 0 0 0 rgba(0, 230, 118, 0); } }
					@keyframes pulseYellow { 0% { box-shadow: 0 0 0 0 rgba(255, 204, 51, 0.7); } 70% { box-shadow: 0 0 0 10px rgba(255, 204, 51, 0); } 100% { box-shadow: 0 0 0 0 rgba(255, 204, 51, 0); } }
					
					.live-indicator-red { width: 12px; height: 12px; background-color: #FF4444; border-radius: 50%; display: inline-block; animation: pulseRed 2s infinite; }
					.live-indicator-green { width: 12px; height: 12px; background-color: #00E676; border-radius: 50%; display: inline-block; animation: pulseGreen 2s infinite; }
					.live-indicator-yellow { width: 12px; height: 12px; background-color: #FFCC33; border-radius: 50%; display: inline-block; animation: pulseYellow 2s infinite; }
					
					.custom-scrollbar::-webkit-scrollbar { width: 6px; }
					.custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
					.custom-scrollbar::-webkit-scrollbar-thumb { background-color: #ccc; border-radius: 10px; }
				`}
			</style>

			<Paper
				elevation={0}
				sx={{
					mb: 4,
					borderRadius: 4,
					background:
						"linear-gradient(135deg, #006633 0%, #004d26 100%)",
					color: "white",
					position: "relative",
					overflow: "hidden",
					display: "flex",
					flexDirection: { xs: "column", md: "row" },
					justifyContent: "space-between",
					alignItems: { xs: "flex-start", md: "center" },
					p: { xs: 3, md: 4 },
					gap: 3,
					boxShadow: "0 10px 30px rgba(0, 102, 51, 0.2)",
				}}
			>
				<Box
					sx={{
						display: "flex",
						alignItems: "center",
						gap: 2,
						zIndex: 1,
					}}
				>
					{currentUser && (
						<Avatar
							src={getOptimizedAvatar(currentUser.profilePic, 60)}
							sx={{
								width: 60,
								height: 60,
								border: "2px solid #FFCC33",
							}}
						>
							{!currentUser.profilePic &&
								currentUser.name?.charAt(0).toUpperCase()}
						</Avatar>
					)}
					<Box>
						<Typography
							variant="h4"
							fontWeight="900"
							sx={{ letterSpacing: "-0.5px", color: "white" }}
						>
							{currentUser
								? `Ready to play, ${currentUser.name.split(" ")[0]}?`
								: "Welcome to GMU Badminton."}
						</Typography>
						<Typography
							variant="body2"
							sx={{ color: "rgba(255,255,255,0.8)", mt: 0.5 }}
						>
							Your command center for matches, schedules, and club
							updates.
						</Typography>
					</Box>
				</Box>

				<Box
					sx={{
						backgroundColor: "rgba(0,0,0,0.3)",
						borderRadius: 4,
						p: 3,
						minWidth: { xs: "100%", md: "380px" },
						zIndex: 1,
						border: "1px solid rgba(255,255,255,0.1)",
						backdropFilter: "blur(10px)",
						boxShadow: "0 8px 32px rgba(0,0,0,0.2)"
					}}
				>
					<Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
						<Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
							<div className={status?.includes('CLOSED') ? 'live-indicator-red' : status?.includes('Active') ? 'live-indicator-yellow' : 'live-indicator-green'}></div>
							<Typography variant="caption" fontWeight="bold" sx={{ color: "rgba(255,255,255,0.9)", letterSpacing: "1px", textTransform: "uppercase" }}>
								Live RAC Status
							</Typography>
						</Box>
						<Chip 
							size="small" 
							label={status?.includes('CLOSED') ? "CLOSED" : status?.includes('Active') ? "HIGH TRAFFIC" : "OPEN PLAY"} 
							sx={{ 
								bgcolor: status?.includes('CLOSED') ? 'rgba(255,68,68,0.2)' : status?.includes('Active') ? 'rgba(255,204,51,0.2)' : 'rgba(0,230,118,0.2)', 
								color: status?.includes('CLOSED') ? '#FF4444' : status?.includes('Active') ? '#FFCC33' : '#00E676', 
								fontWeight: 'bold' 
							}} 
						/>
					</Box>
					
					<Typography variant="h5" fontWeight="900" sx={{ mb: 1, lineHeight: 1.3, color: 'white' }}>
						{loading ? <Skeleton variant="text" width="60%" sx={{ bgcolor: 'rgba(255,255,255,0.1)' }} /> : (status || "Status unavailable")}
					</Typography>
					
					<Box sx={{ mt: 3, mb: 2 }}>
						<Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
							<Typography variant="caption" sx={{ color: 'rgba(255,255,255,0.7)' }}>Estimated Capacity</Typography>
							<Typography variant="caption" fontWeight="bold" sx={{ color: 'white' }}>{status?.includes('CLOSED') ? '0%' : status?.includes('Active') ? '85%' : '40%'}</Typography>
						</Box>
						<Box sx={{ width: '100%', height: 6, bgcolor: 'rgba(255,255,255,0.1)', borderRadius: 3, overflow: 'hidden' }}>
							<Box sx={{ 
								width: status?.includes('CLOSED') ? '0%' : status?.includes('Active') ? '85%' : '40%', 
								height: '100%', 
								bgcolor: status?.includes('CLOSED') ? '#FF4444' : status?.includes('Active') ? '#FFCC33' : '#00E676', 
								borderRadius: 3, 
								transition: 'width 1.5s cubic-bezier(0.16, 1, 0.3, 1)' 
							}} />
						</Box>
					</Box>

					<Button
						fullWidth
						variant="contained"
						color="secondary"
						href="https://connect.recreation.gmu.edu/Facility/GetSchedule?facilityId=4434ce67-8efc-4c48-90e1-7add7f48ad24"
						target="_blank"
						sx={{ fontWeight: "bold", borderRadius: 3, color: "#006633", py: 1, textTransform: 'none' }}
					>
						Check Official Connect Portal ➦
					</Button>
				</Box>
			</Paper>

			<Grid container spacing={{ xs: 2, sm: 3, md: 4 }}>
				<Grid size={{'xs': 12, 'md': 4}}>
					<Box
						sx={{
							display: "flex",
							alignItems: "center",
							gap: 1,
							mb: 2,
						}}
					>
						<Box
							sx={{
								color: "secondary.main",
								display: "flex",
								alignItems: "center",
							}}
						>
							<MegaphoneIcon />
						</Box>
						<Typography
							variant="h5"
							fontWeight="900"
							color="primary"
						>
							Official Updates
						</Typography>
					</Box>

					{currentUser?.role === "admin" && (
						<Paper
							elevation={0}
							sx={{
								p: 2,
								mb: 2,
								borderRadius: 3,
								border: "1px solid #006633",
								backgroundColor: "rgba(0,102,51,0.02)",
							}}
						>
							<Typography
								variant="caption"
								fontWeight="bold"
								color="primary"
								sx={{ mb: 1, display: "block" }}
							>
								👑 Admin Broadcast
							</Typography>
							<TextField
								fullWidth
								multiline
								maxRows={4}
								placeholder="Share news, cancellations, or updates..."
								value={newUpdateText}
								onChange={(e) =>
									setNewUpdateText(e.target.value)
								}
								size="small"
								sx={{
									mb: 1.5,
									"& .MuiOutlinedInput-root": {
										borderRadius: 2,
										backgroundColor: "background.paper",
									},
								}}
							/>
							<Button
								variant="contained"
								color="primary"
								fullWidth
								disabled={!newUpdateText.trim() || isPosting}
								onClick={handlePostUpdate}
								sx={{
									fontWeight: "bold",
									borderRadius: 2,
									textTransform: "none",
								}}
							>
								{isPosting
									? "Broadcasting..."
									: "Post Official Update"}
							</Button>
						</Paper>
					)}

					<Paper
						elevation={0}
						className="custom-scrollbar"
						sx={{
							border: "1px solid", borderColor: "divider",
							borderRadius: 4,
							maxHeight: { xs: "350px", md: "600px" },
							overflowY: "auto",
							overflowX: "hidden",
							backgroundColor: "background.paper",
							display: "flex",
							flexDirection: "column",
							width: "100%", // Force 100% width on the container
						}}
					>
						{loading ? (
							<Box
								sx={{
									display: "flex",
									justifyContent: "center",
									p: 4,
								}}
							>
								<CircularProgress />
							</Box>
						) : announcements.length === 0 ? (
							<Box
								sx={{
									display: "flex",
									flexDirection: "column",
									alignItems: "center",
									p: 4,
									textAlign: "center",
									opacity: 0.5,
									width: "100%",
								}}
							>
								<style>
									{`
										@keyframes floatMsg { 0% { transform: translateY(0px); } 50% { transform: translateY(-10px); } 100% { transform: translateY(0px); } }
										.floating-msg { animation: floatMsg 3s ease-in-out infinite; color: #006633; }
									`}
								</style>
								<div className="floating-msg">
									<MegaphoneIcon
										style={{
											width: 60,
											height: 60,
											marginBottom: 16,
											opacity: 0.7,
										}}
									/>
								</div>
								<Typography variant="h6" fontWeight="bold" sx={{ color: 'text.primary' }}>
									No New Updates
								</Typography>
								<Typography variant="body2" sx={{ color: 'text.secondary', maxWidth: 250, mx: 'auto' }}>
									The court is clear. Check back later for
									official club announcements!
								</Typography>
							</Box>
						) : (
							<Box
								sx={{
									display: "flex",
									flexDirection: "column",
									width: "100%",
								}}
							>
								{announcements.map((announcement, index) => (
									<Box
										key={announcement._id}
										sx={{
											width: "100%", // Guarantee children fill the space
											transition: "all 0.2s",
											"&:hover": {
												backgroundColor: "action.hover",
											},
										}}
									>
										<Box
											sx={{
												p: 3,
												width: "100%",
												boxSizing: "border-box",
											}}
										>
											<Box
												sx={{
													display: "flex",
													justifyContent:
														"space-between",
													alignItems: "flex-start",
													mb: 2,
													width: "100%", // Force header flexbox to take full width
												}}
											>
												<Box
													sx={{
														display: "flex",
														gap: 1.5,
														flexGrow: 1,
													}}
												>
													{" "}
													{/* flexGrow: 1 pushes right side out */}
													<Avatar
														sx={{
															width: 38,
															height: 38,
															bgcolor:
																"primary.main",
															fontWeight: "bold",
														}}
													>
														{announcement.authorName
															.charAt(0)
															.toUpperCase()}
													</Avatar>
													<Box>
														<Box
															sx={{
																display: "flex",
																alignItems:
																	"center",
																gap: 1,
																flexWrap:
																	"wrap",
															}}
														>
															<Typography
																variant="subtitle2"
																fontWeight="bold"
																color="text.primary"
															>
																{
																	announcement.authorName
																}
															</Typography>
															<Chip
																label="Admin"
																size="small"
																color="error"
																variant="outlined"
																sx={{
																	height: 20,
																	fontSize:
																		"0.7rem",
																	fontWeight:
																		"bold",
																}}
															/>
														</Box>
														<Typography
															variant="caption"
															color="text.secondary"
															sx={{
																display:
																	"block",
																mt: 0.2,
															}}
														>
															{formatTime(
																announcement.timestamp,
															)}
														</Typography>
													</Box>
												</Box>

												{/* Delete Button (Only for Admins) */}
												{currentUser?.role ===
													"admin" && (
													<IconButton
														size="small"
														color="error"
														onClick={() =>
															setDeleteUpdateId(
																announcement._id,
															)
														}
														sx={{
															mt: -0.5,
															mr: -0.5,
															flexShrink: 0,
															"&:hover": {
																backgroundColor:
																	"rgba(211, 47, 47, 0.1)",
															},
														}}
													>
														<TrashIcon />
													</IconButton>
												)}
											</Box>

											<Typography
												variant="body1"
												sx={{
													whiteSpace: "pre-wrap",
													wordBreak: "break-word",
													overflowWrap: "anywhere",
													lineHeight: 1.6,
													color: "text.primary",
													width: "100%",
													display: "block",
												}}
											>
												{announcement.content}
											</Typography>
										</Box>
										{index < announcements.length - 1 && (
											<Divider />
										)}
									</Box>
								))}
							</Box>
						)}
					</Paper>
				</Grid>

				<Grid size={{'xs': 12, 'md': 8}}>
					<Typography
						variant="h5"
						fontWeight="900"
						color="primary"
						sx={{ mb: 2 }}
					>
						Live RAC Court Status
					</Typography>
					<Box
						sx={{
							display: "flex",
							flexDirection: "column",
							gap: 2.5,
						}}
					>
						{loading ? (
							[1, 2, 3].map((n) => (
								<Paper
									key={n}
									elevation={0}
									sx={{
										p: 3,
										borderRadius: 3,
										border: "1px solid", borderColor: "divider",
										display: 'flex',
										gap: 2
									}}
								>
									<Skeleton variant="rounded" width={80} height={80} />
									<Box sx={{ flexGrow: 1 }}>
										<Skeleton variant="text" sx={{ fontSize: '1.5rem' }} width="40%" />
										<Skeleton variant="text" sx={{ fontSize: '1rem' }} width="20%" />
									</Box>
								</Paper>
							))
						) : schedule?.timeSlots?.length > 0 ? (
							schedule.timeSlots.map((slot, index) => {
								const getStatusColor = (status) => {
									switch(status) {
										case 'DEDICATED': return 'success.main';
										case 'CLUB_ONLY': return 'info.main';
										case 'OPEN_REQ': return 'warning.main';
										case 'UNAVAILABLE': return 'error.main';
										default: return 'text.secondary';
									}
								};
								
								const getStatusLabel = (status) => {
									switch(status) {
										case 'DEDICATED': return '🟢 Dedicated Drop-in';
										case 'CLUB_ONLY': return '🔵 Club Members Only';
										case 'OPEN_REQ': return '🟡 Open Rec (Ask for Nets)';
										case 'UNAVAILABLE': return '🔴 Unavailable';
										default: return status;
									}
								};

								const startTimeObj = new Date(slot.startTime);
								const startTime = startTimeObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
								const endTime = new Date(slot.endTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
								const dayName = startTimeObj.toLocaleDateString('en-US', { weekday: 'short' });

								return (
									<Paper
										key={index}
										elevation={0}
										sx={{
											display: "flex",
											borderRadius: 4,
											overflow: "hidden",
											border: "1px solid", borderColor: "divider",
											transition: "all 0.2s",
											"&:hover": {
												borderColor: "primary.main",
												boxShadow: "0 4px 15px rgba(0,0,0,0.05)",
											},
										}}
									>
										<Box
											sx={{
												bgcolor: getStatusColor(slot.status),
												color: "white",
												minWidth: { xs: 80, sm: 100 },
												display: "flex",
												flexDirection: "column",
												justifyContent: "center",
												alignItems: "center",
												p: 2,
												textAlign: "center"
											}}
										>
											<Typography variant="caption" fontWeight="bold" sx={{ textTransform: 'uppercase', letterSpacing: '1px', mb: 0.5, opacity: 0.9 }}>
												{dayName}
											</Typography>
											<Typography variant="body2" fontWeight="bold">
												{startTime}
											</Typography>
											<Typography variant="caption" sx={{ opacity: 0.8 }}>
												to
											</Typography>
											<Typography variant="body2" fontWeight="bold">
												{endTime}
											</Typography>
										</Box>
										<Box
											sx={{
												p: { xs: 2, sm: 3 },
												flexGrow: 1,
												display: "flex",
												flexDirection: "column",
												justifyContent: "center",
											}}
										>
											<Box
												sx={{
													display: "flex",
													justifyContent: "space-between",
													alignItems: "flex-start",
													mb: 1,
												}}
											>
												<Typography variant="h6" fontWeight="bold">
													{slot.eventName}
												</Typography>
												<Chip
													label={getStatusLabel(slot.status)}
													size="small"
													sx={{
														fontWeight: "bold",
														borderRadius: 2,
														bgcolor: `${getStatusColor(slot.status)}22`,
														color: getStatusColor(slot.status),
														border: `1px solid ${getStatusColor(slot.status)}`
													}}
												/>
											</Box>
											<Box
												sx={{
													display: "flex",
													flexWrap: "wrap",
													gap: { xs: 1.5, sm: 3 },
													color: "text.secondary",
													mt: 0.5,
												}}
											>
												<Typography
													variant="body2"
													sx={{
														display: "flex",
														alignItems: "center",
														gap: 0.5,
														color: "text.secondary",
													}}
												>
													<PinIcon /> {schedule.facilityName}
												</Typography>
											</Box>
										</Box>
									</Paper>
								);
							})
						) : (
							<Paper
								elevation={0}
								sx={{
									p: 4,
									borderRadius: 3,
									border: "1px solid", borderColor: "divider",
									textAlign: "center",
								}}
							>
								<Typography color="text.secondary">
									No live court schedule available right now.
								</Typography>
							</Paper>
						)}
					</Box>
				</Grid>
			</Grid>

			

			<Dialog
				open={!!deleteUpdateId}
				onClose={() => setDeleteUpdateId(null)}
				PaperProps={{ sx: { borderRadius: 3, p: 1 } }}
			>
				<DialogTitle
					sx={{
						fontWeight: "bold",
						display: "flex",
						alignItems: "center",
						gap: 1,
						color: "error.main",
					}}
				>
					<TrashIconLarge /> Confirm Deletion
				</DialogTitle>
				<DialogContent>
					<Typography>
						Are you sure you want to permanently delete this
						official announcement? This action cannot be undone.
					</Typography>
				</DialogContent>
				<MuiDialogActions sx={{ px: 3, pb: 2 }}>
					<Button
						onClick={() => setDeleteUpdateId(null)}
						color="inherit"
						sx={{ fontWeight: "bold", textTransform: "none" }}
					>
						Cancel
					</Button>
					<Button
						onClick={confirmDeleteUpdate}
						variant="contained"
						color="error"
						sx={{
							fontWeight: "bold",
							textTransform: "none",
							borderRadius: 2,
						}}
					>
						Delete
					</Button>
				</MuiDialogActions>
			</Dialog>
		</Box>
	);
}

import React, { useState, useEffect, useRef, useCallback } from "react";
import apiFetch from "../utils/api";
import { useAuth } from "../context/AuthContext";
import { toast } from "react-hot-toast";
import {
	Typography, Box, Paper, Chip, Fab, Dialog, DialogTitle,
	DialogContent, DialogActions, TextField, useTheme, useMediaQuery,
	Skeleton, CircularProgress, Avatar, Tabs, Tab, Button
} from "@mui/material";
import PostCard from "../components/PostCard";
import socket from "../utils/socket";
import { useNavigate } from "react-router-dom";

export default function Forum() {
	const { user: currentUser } = useAuth();
	const theme = useTheme();
	const fullScreen = useMediaQuery(theme.breakpoints.down("md"));

	const [tab, setTab] = useState("foryou"); // "foryou", "top", "latest"
	const [selectedTag, setSelectedTag] = useState("");
	const [feed, setFeed] = useState([]);
	const [bookmarkedPosts, setBookmarkedPosts] = useState(new Set());
	const [page, setPage] = useState(1);
	const [hasMore, setHasMore] = useState(true);
	const [isLoading, setIsLoading] = useState(true);
	const [isFetchingMore, setIsFetchingMore] = useState(false);
	const observer = useRef();

	const [isModalOpen, setIsModalOpen] = useState(false);
	const [newPost, setNewPost] = useState({ title: "", content: "", imageUrl: "", tags: [] });
	const [postImages, setPostImages] = useState([]);
	const [isUploadingImage, setIsUploadingImage] = useState(false);
	const isFormValid = newPost.title.length > 0 && newPost.content.length > 0;

	const formatTime = (dateString) => {
		if (!dateString) return "";
		return new Date(dateString).toLocaleDateString("en-US", {
			month: "short", day: "numeric", hour: "numeric", minute: "2-digit",
		});
	};

	const lastFeedElementRef = useCallback(node => {
		if (isLoading || isFetchingMore) return;
		if (observer.current) observer.current.disconnect();
		observer.current = new IntersectionObserver(entries => {
			if (entries[0].isIntersecting && hasMore) {
				setPage(prevPage => prevPage + 1);
			}
		});
		if (node) observer.current.observe(node);
	}, [isLoading, isFetchingMore, hasMore]);

	const cursorRef = useRef(null);
	const sessionTimeRef = useRef(null);

	useEffect(() => {
		const fetchFeed = async () => {
			const isFirstPage = page === 1;
			if (isFirstPage) {
				setIsLoading(true);
				cursorRef.current = null;
				// If refresh is manually triggered without tab change, update session time
				if (page === 1 && !cursorRef.current) sessionTimeRef.current = Date.now();
			} else {
				setIsFetchingMore(true);
			}

			try {
				const tagQuery = selectedTag ? `&tag=${encodeURIComponent(selectedTag)}` : "";
				const cursorQuery = cursorRef.current ? `&cursor=${cursorRef.current}` : "";
				const sessionQuery = `&sessionTime=${sessionTimeRef.current}`;
				const res = await apiFetch(`/api/feed?tab=${tab}&limit=10${tagQuery}${cursorQuery}${sessionQuery}`);
				if (res.ok) {
					const data = await res.json();
					cursorRef.current = data.nextCursor;
					setHasMore(!!data.nextCursor);
					if (data.bookmarkedPosts) setBookmarkedPosts(new Set(data.bookmarkedPosts));
					
					if (isFirstPage) {
						setFeed(data.feed);
					} else {
						setFeed(prev => {
							const existingIds = new Set(prev.map(item => item._id));
							const newItems = data.feed.filter(item => !existingIds.has(item._id));
							return [...prev, ...newItems];
						});
					}
				}
			} catch (e) {
				console.error("Failed to load community feed", e);
			} finally {
				setIsLoading(false);
				setIsFetchingMore(false);
			}
		};
		fetchFeed();
	}, [tab, page, selectedTag]);

	// Listen for real-time updates
	useEffect(() => {
		const handleNewPost = () => {
			// No-op: We intentionally DO NOT auto-refresh the feed. 
			// We let the user click the Refresh button so their reading position isn't disrupted.
		};

		const handlePostUpdated = (updatedPost) => {
			// Update likes/comments inline without changing the array order!
			setFeed(prevFeed => prevFeed.map(item => {
				if (item.type === 'post' && item.referenceId === updatedPost._id) {
					const totalComments = updatedPost.comments?.reduce((acc, c) => acc + 1 + (c.replies?.length || 0), 0) || 0;
					return {
						...item,
						likes: updatedPost.likedBy?.length || 0,
						comments: totalComments
					};
				}
				return item;
			}));
		};

		socket.on("postCreated", handleNewPost);
		socket.on("matchConfirmed", handleNewPost);
		socket.on("postUpdated", handlePostUpdated); // For likes/comments

		return () => {
			socket.off("postCreated", handleNewPost);
			socket.off("matchConfirmed", handleNewPost);
			socket.off("postUpdated", handlePostUpdated);
		};
	}, []);

	const handleTabChange = (event, newValue) => {
		setTab(newValue);
		setPage(1);
		setFeed([]);
	};

	const handleSubmit = async () => {
		if (!currentUser) return alert("You must be logged in to post!");
		try {
			setIsUploadingImage(true);
			let finalImageUrls = [];

			if (postImages.length > 0) {
				const formData = new FormData();
				postImages.forEach(file => formData.append("images", file));
				formData.append("type", "postAttachment");
				formData.append("userId", currentUser.id);

				const uploadRes = await apiFetch("/api/upload/images", { method: "POST", body: formData });
				const uploadData = await uploadRes.json();
				if (uploadRes.ok) finalImageUrls = uploadData.imageUrls;
				else {
					setIsUploadingImage(false);
					return toast.error("Failed to upload image. " + uploadData.message);
				}
			}

			// Submit Post (using old Forum API but it creates an ActivityFeed under the hood)
			// Target date is no longer strictly used for filtering, but backend requires it.
			const res = await apiFetch("/api/forum", {
				method: "POST",
				body: JSON.stringify({
					title: newPost.title,
					content: newPost.content,
					imageUrl: finalImageUrls[0] || "",
					imageUrls: finalImageUrls,
					authorName: currentUser.name,
					authorId: currentUser.id,
                    tags: newPost.tags,
					targetDate: new Date().toLocaleDateString("en-US", { month: "short", day: "numeric" }),
				}),
			});

			const data = await res.json();
			setIsUploadingImage(false);
			if (!res.ok) return toast.error(data.message || "Failed to post. Please try again.");

			setNewPost({ title: "", content: "", imageUrl: "", tags: [] });
			setPostImages([]);
			setIsModalOpen(false);
			toast.success("Post created successfully!");
		} catch (error) {
			setIsUploadingImage(false);
			console.error("Failed to post", error);
		}
	};

	return (
		<Box sx={{ pb: 10 }}>
			{/* HERO BANNER */}
			<Box 
				sx={{ 
					width: '100%', mb: 4, py: { xs: 4, md: 6 },
					background: "linear-gradient(135deg, rgba(0, 102, 51, 0.9) 0%, rgba(255, 204, 51, 0.8) 100%)",
					borderRadius: 4,
					position: 'relative', overflow: 'hidden',
					display: 'flex', flexDirection: 'column',
					alignItems: 'center', justifyContent: 'center',
					boxShadow: '0 4px 30px rgba(0, 0, 0, 0.1)',
				}}
			>
				<Typography variant="h3" fontWeight="900" color="white" align="center" sx={{ textShadow: "0px 2px 4px rgba(0,0,0,0.5)", zIndex: 1, mb: 2 }}>
					Community Hub
				</Typography>
				<Typography variant="h6" color="rgba(255,255,255,0.9)" align="center" sx={{ zIndex: 1, px: 2 }}>
					Connect, discuss, and track all the action happening on campus.
				</Typography>
			</Box>

			{/* TABS NAVIGATION */}
			<Box sx={{ width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', mb: 4, gap: 2 }}>
				<Tabs value={tab} onChange={handleTabChange} textColor="primary" indicatorColor="primary" 
					sx={{ 
						'& .MuiTab-root': { fontWeight: 'bold', fontSize: '1.1rem', textTransform: 'none', px: { xs: 2, sm: 4 } },
						background: 'background.paper', borderRadius: 10, boxShadow: 1, p: 0.5
					}}>
					<Tab label="For You" value="foryou" />
					<Tab label="Trending" value="top" />
					<Tab label="Latest" value="latest" />
				</Tabs>

				{/* ACTION BAR (TRENDING TAGS + REFRESH) */}
				<Box 
					sx={{ 
						width: '100%', maxWidth: '800px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1, gap: 2
					}}
				>
                    <Box 
                        sx={{ 
                            display: 'flex', gap: 1, overflowX: 'auto', pb: 1, flex: 1,
                            '&::-webkit-scrollbar': { display: 'none' }, // Hide scrollbar for clean UI
                            msOverflowStyle: 'none', scrollbarWidth: 'none' 
                        }}
                    >
                        <Chip label="Trending" size="small" sx={{ fontWeight: 'bold', background: 'linear-gradient(45deg, #FF512F 0%, #F09819 100%)', color: 'white' }} />
                        {['Tournament', 'RAC', 'Stringing', 'Doubles', 'Equipment'].map((tag) => (
                            <Chip 
                                key={tag} 
                                label={tag} 
                                size="small" 
                                variant={selectedTag === tag ? "filled" : "outlined"}
                                color={selectedTag === tag ? "primary" : "default"}
                                onClick={() => {
                                    setSelectedTag(selectedTag === tag ? "" : tag);
                                    setPage(1);
                                }}
                                sx={{ 
                                    fontWeight: 'bold', cursor: 'pointer', 
                                    '&:hover': { bgcolor: 'primary.main', color: 'white', borderColor: 'primary.main' } 
                                }} 
                            />
                        ))}
                    </Box>

                    <Button 
                        variant="outlined" 
                        size="small" 
                        color="inherit"
                        onClick={() => { setPage(1); setFeed([]); }}
                        sx={{ minWidth: 'auto', borderRadius: 2, display: 'flex', gap: 1, fontWeight: 'bold', height: 26 }}
                    >
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21.5 2v6h-6M2.13 15.57a9 9 0 1 0 3.12-11.83l-4.75 4.76"/></svg>
                        <Box sx={{ display: { xs: 'none', sm: 'block' } }}>Refresh</Box>
                    </Button>
				</Box>

			</Box>
			{/* FEED */}
			<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, width: '100%', maxWidth: '680px', mx: 'auto' }}>
				{isLoading ? (
					[1, 2, 3, 4].map(n => (
						<Paper key={n} elevation={0} sx={{ p: 3, borderRadius: 4, border: "1px solid", borderColor: "divider", mb: 2, width: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                <Skeleton variant="circular" width={40} height={40} />
                                <Box sx={{ ml: 2, width: '100%' }}>
                                    <Skeleton variant="text" width="60%" height={24} />
                                    <Skeleton variant="text" width="40%" height={20} />
                                </Box>
                            </Box>
                            <Skeleton variant="rounded" height={100} sx={{ borderRadius: 2 }} />
                        </Paper>
					))
				) : feed.length === 0 ? (
					<Box sx={{ width: '100%', display: 'flex', justifyContent: 'center', p: 4 }}>
						<Typography color="text.secondary">No activity found.</Typography>
					</Box>
				) : (
					feed.map((item, idx) => {
						if (item.type === 'post') {
							// Transform ActivityFeed back to Post format for PostCard component
							const mockPost = {
								_id: item.referenceId,
								title: item.title,
								content: item.content,
								imageUrl: item.image,
								imageUrls: item.images || [],
								authorId: item.authorId,
								authorName: item.authorName,
								authorBadges: item.authorBadges,
								timestamp: item.createdAt,
                                tags: item.tags || [],
								likedBy: new Array(Math.max(0, item.likes || 0)).fill('mock_id'), // PostCard only cares about length
								recentLikerAvatars: item.recentLikerAvatars || [],
																comments: new Array(Math.max(0, item.comments || 0)).fill({}), 
							};
							return (
								<Box key={item._id} ref={idx === feed.length - 1 ? lastFeedElementRef : null} sx={{ width: '100%' }}>
									<PostCard post={mockPost} currentUser={currentUser} isBookmarked={bookmarkedPosts.has(item.referenceId)} onBookmarkToggle={(isBookmarked) => setBookmarkedPosts(prev => { const n = new Set(prev); if(isBookmarked) n.add(item.referenceId); else n.delete(item.referenceId); return n; })} onDelete={() => {}} />
								</Box>
							);
						}
						
						if (item.type === 'match') {
							const team1Wins = item.team1Score > item.team2Score;
							const team2Wins = item.team2Score > item.team1Score;

							return (
								<Box key={item._id} ref={idx === feed.length - 1 ? lastFeedElementRef : null} sx={{ width: '100%' }}>
									<Paper 
										elevation={0} 
										sx={{ 
											p: 0, borderRadius: 4, overflow: 'hidden', border: "1px solid", borderColor: "divider", 
											display: 'flex', flexDirection: 'column',
											background: 'linear-gradient(135deg, rgba(0, 102, 51, 0.05) 0%, rgba(255, 204, 51, 0.05) 100%)',
											transition: '0.3s cubic-bezier(0.16, 1, 0.3, 1)',
											'&:hover': {
												transform: 'scale(1.02) translateY(-4px)',
												boxShadow: '0 12px 30px rgba(0,102,51,0.15)',
												borderColor: 'primary.main'
											}
										}}
									>
										{/* HEADER BAR */}
										<Box sx={{ display: 'flex', px: 3, py: 1.5, background: 'rgba(0,0,0,0.03)', borderBottom: '1px solid rgba(0,0,0,0.05)', alignItems: 'center' }}>
											<Chip label="🏆 Official Match" size="small" sx={{ fontWeight: 'bold', background: 'linear-gradient(45deg, #FFD700 0%, #FFA500 100%)', color: 'black' }} />
											<Typography variant="caption" fontWeight="bold" color="text.secondary" ml="auto">{formatTime(item.createdAt)}</Typography>
										</Box>

										{/* SCOREBOARD */}
										<Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', p: 3, position: 'relative' }}>
											{/* TEAM 1 */}
											<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1.5, width: '35%', position: 'relative' }}>
												{team1Wins && <Box sx={{ position: 'absolute', top: -20, fontSize: '1.5rem',  }}>👑</Box>}
												<Box sx={{ display: 'flex' }}>
													{item.team1Avatars?.map((avatar, i) => (
														<Avatar key={i} src={avatar} sx={{ width: 56, height: 56, ml: i > 0 ? -2 : 0, border: '3px solid', borderColor: team1Wins ? '#FFD700' : 'background.paper', zIndex: 2 - i, boxShadow: 2 }} />
													))}
												</Box>
												<Typography variant="body2" fontWeight="900" textAlign="center" sx={{ width: '100%', wordWrap: 'break-word', lineHeight: 1.2 }}>
													{item.team1?.map(name => name.split(' ')[0]).join(' & ')}
												</Typography>
											</Box>

											{/* HUGE SCORE */}
											<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '30%' }}>
												<Typography variant="overline" color="text.secondary" fontWeight="bold" sx={{ mb: -1 }}>FINAL</Typography>
												<Typography variant="h3" fontWeight="900" sx={{ letterSpacing: '-2px', color: 'text.primary' }}>
													<span style={{ color: team1Wins ? '#006633' : 'inherit' }}>{item.team1Score}</span>
													<span style={{ margin: '0 8px', color: '#ccc' }}>-</span>
													<span style={{ color: team2Wins ? '#006633' : 'inherit' }}>{item.team2Score}</span>
												</Typography>
											</Box>

											{/* TEAM 2 */}
											<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1.5, width: '35%', position: 'relative' }}>
												{team2Wins && <Box sx={{ position: 'absolute', top: -20, fontSize: '1.5rem',  }}>👑</Box>}
												<Box sx={{ display: 'flex' }}>
													{item.team2Avatars?.map((avatar, i) => (
														<Avatar key={i} src={avatar} sx={{ width: 56, height: 56, ml: i > 0 ? -2 : 0, border: '3px solid', borderColor: team2Wins ? '#FFD700' : 'background.paper', zIndex: 2 - i, boxShadow: 2 }} />
													))}
												</Box>
												<Typography variant="body2" fontWeight="900" textAlign="center" sx={{ width: '100%', wordWrap: 'break-word', lineHeight: 1.2 }}>
													{item.team2?.map(name => name.split(' ')[0]).join(' & ')}
												</Typography>
											</Box>
										</Box>
									</Paper>
								</Box>
							);
						}
						
						return null;
					})
				)}
			</Box>
			
			<Box sx={{ display: 'flex', justifyContent: 'center', mt: 4, height: 60, alignItems: 'center' }}>
				{isFetchingMore && <CircularProgress size={24} color="primary" />}
                {!isFetchingMore && !hasMore && feed.length > 0 && (
                    <Typography variant="body2" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                        You're all caught up! 🏸
                    </Typography>
                )}
			</Box>

			{/* Floating Action Button */}
			<Fab
				color="primary"
				aria-label="add"
				sx={{ position: "fixed", bottom: { xs: 80, sm: 40 }, right: { xs: 20, sm: 40 }, zIndex: 1000 }}
				onClick={() => setIsModalOpen(true)}
			>
				<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
			</Fab>

			{/* Create Post Modal */}
			<Dialog fullScreen={fullScreen} open={isModalOpen} onClose={() => setIsModalOpen(false)} PaperProps={{ sx: { borderRadius: 3, p: 1 } }}>
				<DialogTitle sx={{ fontWeight: "bold", fontSize: "1.5rem" }}>Create a Post</DialogTitle>
				<DialogContent sx={{ display: "flex", flexDirection: "column", gap: 3, mt: 1 }}>
					<TextField label="Title" variant="outlined" fullWidth value={newPost.title} onChange={(e) => setNewPost({ ...newPost, title: e.target.value })} />
					<TextField label="What's on your mind?" multiline rows={4} variant="outlined" fullWidth value={newPost.content} onChange={(e) => setNewPost({ ...newPost, content: e.target.value })} />
					
                    {/* Tags Selection */}
                    <Box>
                        <Typography variant="caption" color="text.secondary" fontWeight="bold" sx={{ mb: 1, display: 'block' }}>
                            Add Tags (Optional)
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                            {['Tournament', 'RAC', 'Stringing', 'Doubles', 'Equipment'].map(tag => {
                                const isSelected = newPost.tags.includes(tag);
                                return (
                                    <Chip 
                                        key={tag}
                                        label={tag}
                                        size="small"
                                        variant={isSelected ? "filled" : "outlined"}
                                        color={isSelected ? "primary" : "default"}
                                        onClick={() => {
                                            if (isSelected) {
                                                setNewPost(p => ({ ...p, tags: p.tags.filter(t => t !== tag) }));
                                            } else if (newPost.tags.length < 3) {
                                                setNewPost(p => ({ ...p, tags: [...p.tags, tag] }));
                                            }
                                        }}
                                        sx={{ cursor: 'pointer' }}
                                    />
                                );
                            })}
                        </Box>
                    </Box>

                    <Box>
						<input accept="image/*" style={{ display: "none" }} id="post-image-upload" type="file" multiple onChange={(e) => {
							const files = Array.from(e.target.files);
							if (files.length > 4) return alert("Maximum 4 images allowed");
							setPostImages(files);
						}} />
						<label htmlFor="post-image-upload">
							<Button variant="outlined" component="span" fullWidth color={postImages.length > 0 ? "success" : "primary"}>
								{postImages.length > 0 ? `Selected: ${postImages.length} image(s)` : "Attach Image(s) (Max 4)"}
							</Button>
						</label>
					</Box>
				</DialogContent>
				<DialogActions sx={{ px: 3, pb: 2 }}>
					<Button onClick={() => setIsModalOpen(false)} color="inherit" sx={{ fontWeight: "bold" }}>Cancel</Button>
					<Button onClick={handleSubmit} variant="contained" disabled={!isFormValid || isUploadingImage} sx={{ fontWeight: "bold", px: 4, borderRadius: 2 }}>
						{isUploadingImage ? <CircularProgress size={24} color="inherit" /> : "Post"}
					</Button>
				</DialogActions>
			</Dialog>
		</Box>
	);
}

import React from "react";
import { Box, Typography, Button, Container, Grid, Paper, useTheme } from "@mui/material";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";

export default function Landing() {
	
	const navigate = useNavigate();

	const containerVariants = {
		hidden: { opacity: 0 },
		visible: {
			opacity: 1,
			transition: { staggerChildren: 0.2, delayChildren: 0.1 },
		},
	};

	const itemVariants = {
		hidden: { y: 30, opacity: 0 },
		visible: {
			y: 0,
			opacity: 1,
			transition: { type: "spring", stiffness: 100 },
		},
	};

	return (
		<Box sx={{ minHeight: "100vh", pt: { xs: 8, md: 12 }, pb: 8 }}>
			<Container maxWidth="lg" component={motion.div} variants={containerVariants} initial="hidden" animate="visible">
				{/* Hero Section */}
				<Box sx={{ textAlign: "center", mb: 8 }}>
					<motion.img
						src="/icon.jpg"
						alt="GMU Badminton"
						style={{ width: 120, height: 120, borderRadius: 24, marginBottom: 24, boxShadow: "0px 12px 24px rgba(0,0,0,0.2)" }}
